/**
 * Shared types mirroring the FastAPI backend response schemas.
 */

export interface FeedHealth {
  status: string;
  app: string;
  feed: {
    routes: number;
    trips: number;
    stops: number;
    stop_times: number;
    /** Publisher's validity window from feed_info.txt — which schedule era
     * the numbers on screen describe. */
    vintage?: {
      start_date: string | null;
      end_date: string | null;
      version: string | null;
    } | null;
  };
  data_freshness?: string | null;
}

export interface RouteFeature {
  type: 'Feature';
  properties: {
    route_id: string;
    route_short_name: string;
    route_long_name: string;
    length_km: number;
    straight_km: number;
    circuity: number;
    flagged: boolean;
    direction_id?: number | null;
    directions?: number[];
    one_way?: boolean;
    proposed_split?: {
      route_id: string;
      route_short_name: string;
      trunk_geometry: [number, number][];
      trunk_circuity: number;
      trunk_length_km: number;
      trunk_start_terminal: string;
      trunk_end_terminal: string;
      trunk_start_terminal_dist_km: number;
      trunk_end_terminal_dist_km: number;
      /** When the trunk borrows another route's direct alignment (corridor
       * splice), the short name of that donor route (e.g. "44").
       */
      donor_route?: string | null;
      /** Where the trunk came from: "donor" (borrowed an existing route's
       * corridor), "network" (a NEW direct line routed over the street
       * network), or "meander" (a cut of the route's own shape).
       */
      trunk_source?: 'donor' | 'network' | 'meander' | string | null;
      /** Route's existing headway (min) — the baseline each piece compares to. */
      route_headway_min?: number | null;
      /** Allocated headway (min) for the trunk, or null when unavailable. */
      trunk_headway_min?: number | null;
      /** How the headway allocation was derived (e.g. "ridership_weighted"). */
      headway_method?: string | null;
      /** For corridor splices: the two junctions where the route leaves the
       * donor corridor (A) and rejoins it (B), with nearest-stop labels.
       */
      splice_junctions?: { lat: number; lon: number; label: string }[] | null;
      branches: {
        geometry: [number, number][];
        circuity: number;
        length_km: number;
        start_terminal: string;
        end_terminal: string;
        start_terminal_dist_km: number;
        end_terminal_dist_km: number;
        /** Allocated headway (min) for this feeder, or null when unavailable. */
        headway_min?: number | null;
      }[];
    };
  };
  geometry: {
    type: 'LineString';
    coordinates: [number, number][];
  };
}

export interface CircuityGeoJSON {
  type: 'FeatureCollection';
  features: RouteFeature[];
  metadata: {
    flag_threshold: number;
    flagged_count: number;
    total_routes: number;
    crs: string;
    period?: string;
    periods?: Record<string, TimePeriod>;
  };
}

export interface CircuitySummaryRoute {
  route_id: string;
  route_short_name: string;
  route_long_name: string;
  circuity: number;
  length_km: number;
  straight_km: number;
}

export interface MissedTransferConnection {
  stop_id: string;
  stop_name: string;
  stop_lat: number;
  stop_lon: number;
  route_i: string;
  route_j: string;
  arr_time: string;
  dep_time: string;
  wait_minutes: number;
  headway_minutes: number;
  weight: number;
  cost_minutes: number;
  reason: 'too long' | 'too short';
  /** True when a ±max_shift re-phase could bring this wait under t_max (i.e. it is
   * a real missed transfer the optimizer can rescue). False for un-shiftable
   * long-headway/wait waits -- those live in the Blind spots tab, not the Home hook.
   */
  shiftable_within_max: boolean;
  /** When set, the departing bus's whole remaining ride is within walking distance,
   * so a missed rider walks instead of waiting one full headway. Minutes to the
   * bus's farthest downstream stop; used to cap the miss cost.
   */
  walk_alternative_minutes: number | null;
  /** Compass direction of each route's actual trip (e.g. 'northbound'), from the
   * trip headsign; '' when the headsign carries no compass token.
   */
  direction_i: string;
  direction_j: string;
  /** Daily APC boardings of each route (Oct 2024); frequency proxy when no row. */
  route_i_boardings?: number;
  route_j_boardings?: number;
  /** Conservative rider estimate at this stop: geometric mean of the pair's
   * boardings x CONNECTION_RIDERSHARE. Absent on old cached rows. */
  est_riders_per_day?: number;
  /** Minutes a fix would save per missed rider (overshoot past the cap). */
  excess_wait_minutes?: number;
  /** Annualized rider-minutes: est riders x excess wait x service days/yr. */
  rider_minutes_per_year?: number;
  /** How the optimizer fixes this ('re-phase (revenue-neutral)' etc). */
  fix_kind?: string;
  /** Net annual operating cost of the fix (0 for re-phases). */
  fix_net_annual_cost?: number;
  /** Ward where the wait happens (delay location, NOT rider residence). */
  delay_ward?: string;
  /** P(this scheduled connection actually fails), from observed lateness;
   * null when either route lacks enough observations. */
  real_miss_probability?: number | null;
  /** P(miss) x service days per week (e.g. 5 for weekdays). */
  real_misses_per_week?: number | null;
  /** Scheduled wait + median(real lateness delta); > scheduled wait means
   * riders wait longer in practice. */
  real_median_wait_minutes?: number | null;
  /** Min observed departures across the two routes backing the figures. */
  lateness_n?: number | null;
  /** When set, the same departing bus can be caught LATER on the arriving
   * trip's path with a shorter total wait -- "ride on and catch it at the
   * next stop". Present only when strictly better in total elapsed time,
   * so a kept over-cap wait explains itself on the card. */
  ride_on_alternative?: {
    stop_name: string;
    stop_id: string;
    /** Minutes riding the arriving bus to the alternative stop. */
    ride_minutes: number;
    /** Minutes waiting at the alternative stop for the same departing bus. */
    wait_minutes: number;
    /** Stops between the wait and the alternative on the arriving trip. */
    stops_away: number;
    /** ride_minutes + wait_minutes. */
    total_minutes: number;
  } | null;
}

export interface TopMissedResponse {
  connections: MissedTransferConnection[];
  period: string;
  /** Service day the ranking was computed for ('weekday' | 'saturday' | 'sunday'). */
  service_day?: string;
}

export type BlindspotCategory = 'modeled' | 'hidden' | 'just_missed';

export interface BlindspotConnection {
  stop_id: string;
  stop_name: string;
  stop_lat: number;
  stop_lon: number;
  route_i: string;
  route_j: string;
  arr_time: string;
  dep_time: string;
  prev_dep_time: string | null;
  wait_minutes: number;
  headway_minutes: number;
  weight: number;
  cost_minutes: number;
  reason: 'too long' | 'too short';
  category: BlindspotCategory;
  shift_to_fix_minutes: number | null;
  shiftable_within_max: boolean;
  /** Compass direction of each route's actual trip (e.g. 'northbound'); '' when
   * the headsign carries no compass token.
   */
  direction_i: string;
  direction_j: string;
}

export interface BlindspotsResponse {
  period: string;
  t_max: number;
  buffer_minutes: number;
  default_window_minutes: number;
  search_horizon_minutes: number;
  summary: {
    n: number;
    total_damaging: number;
    modeled: number;
    hidden: number;
    just_missed: number;
    shiftable_within_max: number;
    not_shiftable: number;
    worst_wait_minutes: number | null;
    worst_headway_minutes: number | null;
  };
  connections: BlindspotConnection[];
}

/** The flagged route worth piloting a trunk + feeder redesign on: the split
 * proposal with the most weekday riders (surfaces Route 10, not just the most
 * winding route, which is often a low-ridership local loop like the 36). */
export interface BestPilotRoute extends CircuitySummaryRoute {
  flagged: boolean;
  weekday_boardings: number | null;
  /** Weekday bus-runs (both directions) from the GTFS trips table. */
  weekday_trips: number | null;
  /** Load factor: weekday_boardings / weekday_trips. */
  riders_per_bus: number | null;
  trunk_circuity: number;
  trunk_length_km: number;
  trunk_start_terminal: string;
  trunk_end_terminal: string;
  /** Existing route whose corridor the proposed trunk borrows, when any. */
  donor_route: string | null;
  trunk_source: string | null;
}

export interface BestPilotResponse {
  route: BestPilotRoute | null;
  period: string;
}

/* ---- route gaps (terminal corridor seams) ---- */

/** One side of a corridor at a terminal (its "leg"). */
export interface CorridorGapLeg {
  /** Compass direction of the leg from the terminal (e.g. "NW"). */
  side: string;
  n_stops: number;
  routes: string[];
  /** True when this leg's routes terminate at the terminal. */
  terminates_at_terminal: boolean;
  /** Name of the leg stop closest to the terminal. */
  nearest_stop: string;
  /** Corridor stop geometry, ordered nearest-to-terminal first (for the map). */
  stops_geo: { id: string; name: string; lat: number; lon: number }[];
}

/** A street corridor severed at a terminal: no route runs through. */
export interface CorridorGap {
  terminal: string;
  corridor: string;
  n_terminating_routes: number;
  terminating_routes: string[];
  /** Approximate average-weekday boardings carried by the terminating routes. */
  boardings: number;
  legs: CorridorGapLeg[];
  story: string;
  /** Terminal coordinates for the map marker. */
  terminal_geo: { name: string; lat: number; lon: number };
}

export interface CorridorGapsResponse {
  seams: CorridorGap[];
  count: number;
  note: string;
}

/** Corridor seam as priced in the executive brief (extension fix costed). */
export interface BriefSeam {
  corridor: string;
  terminal: string;
  story: string;
  boardings: number;
  legs: {
    side: string;
    routes: string[];
    terminates_at_terminal: boolean;
  }[];
  gap_km: number;
  trips_per_day: number;
  added_hours_per_day: number;
  est_annual_extension_cost: number;
  cost_note: string;
}

