/* ---- measured transfer reliability (map) ---- */

/** One transfer node's realized (measured) wait + miss probability. */
export interface ReliabilityNode {
  stop_id: string;
  stop_name: string;
  lat: number;
  lon: number;
  routes: string[];
  /** route number -> most common GTFS headsign among this node's trips of
      that route (e.g. "38" -> "38 N Creditview To Meadowvale"). Lets the
      rider see WHERE each bus goes before committing to a pair. */
  route_headsigns?: Record<string, string>;
  scheduled_median_min: number | null;
  realized_median_min: number | null;
  realized_p90_min: number | null;
  delta_median_min: number | null;
  p_miss: number;
  measured_share: number;
  n_connections: number;
}

/** Rider-facing "Will I make it?" check (P5.5). Uncertainty-language verdict:
 * likely / tight / unlikely / unknown — 'unknown' when the route pair lacks
 * enough observed data (the honest fallback, never a guessed verdict). */
export interface TripCheckResponse {
  found: boolean;
  measured?: boolean;
  reason?: string;
  stop_id?: string;
  stop_name?: string;
  route_arrive?: string;
  route_depart?: string;
  scheduled_wait_min?: number;
  walk_min?: number;
  slack_minutes?: number;
  /** GTFS headsign of the arriving bus (where it's headed). */
  headsign_arrive?: string | null;
  /** GTFS headsign of the departing bus (where it's headed). */
  headsign_depart?: string | null;
  /** An earlier stop on the SAME arriving bus where this route pair also
      connects (same or shorter wait) — e.g. Bayberry before Dalehurst. */
  earlier_alternative?: {
    stop_id: string;
    stop_name: string;
    scheduled_wait_min: number;
    walk_min: number;
    stops_earlier: number;
  } | null;
  realized_median_wait_min?: number;
  p_miss?: number;
  n_obs_arrive?: number;
  n_obs_depart?: number;
  verdict: 'likely' | 'tight' | 'unlikely' | 'unknown' | null;
  message: string;
  method?: string;
}

