export interface OptimizeResponse {
  status: string;
  /** Solver certificate: 'OPTIMAL' (provably within the gap limit of the
   * best possible schedule) or 'FEASIBLE' (the time budget expired first —
   * good, but more compute could still improve it). */
  solve_duration_seconds?: number | null;
  /** For FEASIBLE runs: remaining headroom vs the solver's best bound, in %
   * of the objective — what a longer run could still close. Null when
   * OPTIMAL (0 by definition) or the bound was unusable. */
  bound_gap_pct?: number | null;
  /** Estimated run-to-run variance for FEASIBLE solves (network-level
   * passenger-minutes saved). Based on observed spread across identical-config
   * runs: ±1% for network, larger for ward/stop level. Null for OPTIMAL. */
  solver_variance_pct?: number | null;
  offsets: OffsetInfo[];
  baseline_avg_wait: number;
  optimized_avg_wait: number;
  baseline_missed: number;
  optimized_missed: number;
  total_connections: number;
  total_kept: number;
  passenger_minutes_saved: number;
  connection_health: number;
  wait_distribution_baseline: number[];
  wait_distribution_optimized: number[];
  nodes: TransferNode[];
  updated_stop_times_available: boolean;
  ridership_impact?: RidershipImpact | null;
  fleet_feasibility?: FleetFeasibility | null;
  route_impacts?: RouteImpact[];
}

