/* ---- operations (measured trends) ---- */

/** One collection day's measured summary from ``weekly_rollup.csv``. */
export interface WeeklyRollupRow {
  date: string;
  /** True when the GTFS feed marks this date as statutory holiday service. */
  is_holiday?: boolean;
  windows_completed: number;
  windows_partial: number;
  windows_missed: number;
  am_polled: number;
  /** Raw GTFS-RT trip-update snapshots the collector polled that day — a
   * COLLECTION metric (scales with polling cadence), not service volume.
   * Never compare it week-over-week; use n_recorded. */
  observations: number;
  verifiable_trips: number;
  ghost_trips: number;
  boardings_lower_pax: number;
  /** Unique recorded departures (horizon-0 observations) — the honest
   * service-volume unit for day-over-day and week-over-week comparison. */
  n_recorded: number;
  pct_early_gt2: number;
  ghost_rate_pct: number;
}

export interface WeekOverWeekAgg {
  days: number;
  /** Recorded departures summed over the week's comparable days.
   * (Formerly `observations` — the poll-snapshot count, which tracks
   * collection cadence rather than service volume.) */
  n_recorded: number;
  ghost_trips: number;
  verifiable_trips: number;
  pct_early_gt2: number | null;
  ghost_rate_pct: number | null;
}

export interface WeekOverWeek {
  this_week: WeekOverWeekAgg;
  previous_week: WeekOverWeekAgg;
  /** Per-comparable-day recorded-departure delta. (Formerly
   * `observations_change_pct` on the poll-snapshot count.) */
  recorded_change_pct: number | null;
  ghost_rate_change_pct: number | null;
  pct_early_change_pp: number | null;
  /** Holidays excluded from both windows (informational). */
  n_holiday_days_skipped: number;
  /** True when the previous week's rows are from a different timetable block
   * (e.g. the Sept 8 schedule change) — the delta is the new schedule, not a
   * service trend, so the frontend annotates rather than reports it as one. */
  spans_schedule_change?: boolean;
}

export interface RollingTrendPoint {
  date: string;
  ghost_rate_pct: number | null;
  pct_early_gt2: number | null;
}

export interface AnomalyMetric {
  value: number;
  baseline_mean: number;
  z: number;
  direction: 'high' | 'low';
}

export interface TrendAnomaly {
  date: string;
  is_holiday: boolean;
  is_weekend: boolean;
  metrics: Partial<Record<'ghost_rate_pct' | 'pct_early_gt2', AnomalyMetric>>;
}

export interface OperationsTrends {
  available: boolean;
  file?: string;
  updated_at?: string | null;
  /** The feed-derived timetable-block boundary (YYYYMMDD): when the current
   * schedule era began. Null when underivable from the feed. */
  schedule_block_boundary?: string | null;
  rows: WeeklyRollupRow[];
  /** Week-over-week over non-holiday weekdays; null until 2+ comparable weeks. */
  week_over_week?: WeekOverWeek | null;
  /** When week_over_week is null, why — rendered verbatim as the empty-state
   * note (e.g. the previous week is entirely pre-schedule-change). */
  wow_unavailable_reason?: string | null;
  /** Trailing 7-comparable-day rolling means, one point per row. */
  rolling?: RollingTrendPoint[];
  /** Days >3σ off the holiday-clean trailing baseline. */
  anomalies?: TrendAnomaly[];
}

