import { useCallback, useEffect, useRef, useState } from 'react';
import {
  ArrowRight,
  Clock,
  Loader2,
  MapPin,
  MousePointerClick,
  Route,
  Sparkles,
  Timer,
  Zap,
} from 'lucide-react';
import { api } from '../lib/api';
import type {
  OptimizeRequest,
  TravelCompareResponse,
  TravelItinerary,
  TravelPoint,
  TravelStopResult,
} from '../types';
import NewHereHint from './NewHereHint';

/**
 * Travel planner: plan the same journey on today's schedule and on the
 * optimizer's shifted schedule, and show how much time riders save.
 * Origins/destinations can be typed (stop search) or clicked on the map.
 */

export interface TravelPicks {
  origin: TravelPoint | null;
  destination: TravelPoint | null;
  nextPick: 'origin' | 'destination';
}

interface Props {
  picks: TravelPicks;
  onPicksChange: React.Dispatch<React.SetStateAction<TravelPicks>>;
  serviceDay: 'weekday' | 'saturday' | 'sunday';
  onItineraries: (itin: Pick<
    TravelCompareResponse,
    'baseline' | 'optimized' | 'origin' | 'destination'
  > | null) => void;
  /** The optimizer settings currently shown in the Improve-transfers tab, so
   * the "optimized" schedule here matches what a run there would produce
   * instead of silently using backend defaults. */
  optimizerSettings: OptimizeRequest;
}

function minToLabel(mins: number): string {
  const total = Math.round(mins);
  const h = Math.floor(total / 60) % 24;
  const m = total % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function labelToMin(label: string): number {
  const [h, m] = label.split(':').map(Number);
  return (h * 60 + (m || 0)) % (24 * 60);
}

function fmtClock(mins: number | null | undefined): string {
  return mins == null ? '—' : minToLabel(mins);
}

function ItineraryCard({
  title,
  accent,
  itin,
}: {
  title: string;
  accent: string;
  itin: TravelItinerary;
}) {
  return (
    <div className="rounded-xl border border-border bg-card">
      <div className="flex items-center justify-between border-b border-border px-3 py-2">
        <span className={`text-[11px] font-bold uppercase tracking-wide ${accent}`}>{title}</span>
        <span className="text-[11px] text-text-muted">
          {fmtClock(itin.depart_at)} → {fmtClock(itin.arrive_at)} ·{' '}
          {itin.transfers === 0 ? 'direct' : `${itin.transfers} transfer${itin.transfers > 1 ? 's' : ''}`}
        </span>
      </div>
      <div className="flex flex-col divide-y divide-border/60">
        {itin.legs.map((leg, i) =>
          leg.kind === 'bus' ? (
            <div key={i} className="px-3 py-2">
              <div className="flex items-center gap-2">
                <span
                  className={`rounded px-1.5 py-0.5 text-[10px] font-bold text-white ${
                    accent === 'text-optimized' ? 'bg-optimized' : 'bg-text-muted'
                  }`}
                >
                  {leg.route}
                </span>
                <span className="text-[11px] font-semibold text-text-primary">
                  {fmtClock(leg.board_time)} → {fmtClock(leg.alight_time)}
                </span>
                <span className="ml-auto text-[10px] text-text-muted">{leg.minutes.toFixed(0)} min</span>
              </div>
              <p className="mt-1 truncate text-[10px] text-text-muted">
                {leg.board_stop} → {leg.alight_stop}
              </p>
            </div>
          ) : (
            <div key={i} className="flex items-center gap-2 px-3 py-2">
              <span className="text-[10px] uppercase tracking-wide text-text-muted">Walk</span>
              <span className="text-[11px] text-text-secondary">{leg.minutes.toFixed(0)} min</span>
              {leg.distance_m != null && (
                <span className="text-[10px] text-text-muted">· {Math.round(leg.distance_m)} m</span>
              )}
              {leg.from && leg.to && (
                <span className="ml-auto truncate text-[10px] text-text-muted">
                  {leg.from} → {leg.to}
                </span>
              )}
            </div>
          )
        )}
      </div>
      <div className="border-t border-border bg-card-hover/60 px-3 py-1.5 text-[10px] text-text-muted">
        Total <b className="text-text-primary">{itin.total_minutes.toFixed(0)} min</b>
      </div>
    </div>
  );
}

function StopInput({
  label,
  value,
  onChange,
  accent,
}: {
  label: string;
  value: TravelPoint | null;
  onChange: (p: TravelPoint | null) => void;
  accent: 'origin' | 'destination';
}) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<TravelStopResult[]>([]);
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);
  // Monotonic request counter: a slow earlier response must not overwrite a
  // newer query's results (typing "Squ" then "Square" can resolve out of order).
  const searchSeq = useRef(0);

  useEffect(() => {
    if (value) setQuery(value.name ?? '');
  }, [value]);

  useEffect(() => {
    const onDoc = (e: MouseEvent) => {
      if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, []);

  const search = useCallback(
    async (q: string) => {
      setQuery(q);
      onChange(null);
      if (q.trim().length < 2) {
        searchSeq.current += 1; // invalidate any in-flight request
        setResults([]);
        setOpen(false);
        return;
      }
      const seq = ++searchSeq.current;
      setBusy(true);
      try {
        const r = await api.travelStops(q);
        if (seq !== searchSeq.current) return; // stale response
        setResults(r.results);
        setOpen(true);
      } catch {
        if (seq !== searchSeq.current) return;
        setResults([]);
      } finally {
        if (seq === searchSeq.current) setBusy(false);
      }
    },
    [onChange]
  );

  const dot = accent === 'origin' ? 'bg-optimized' : 'bg-accent';

  return (
    <div className="relative" ref={boxRef}>
      <label className="mb-1 flex items-center gap-1 text-[10px] font-semibold uppercase tracking-wide text-text-muted">
        <MapPin className={`h-3 w-3 ${dot}`} />
        {label}
      </label>
      <div className="flex items-center gap-1.5 rounded-lg border border-border bg-card-hover px-2 py-1.5">
        <span className={`h-2 w-2 shrink-0 rounded-full ${dot}`} />
        <input
          value={query}
          onChange={(e) => search(e.target.value)}
          onFocus={() => query.trim().length >= 2 && setOpen(true)}
          placeholder={value?.mode === 'point' ? 'Picked on map — type to use a stop' : 'Search stop name…'}
          className="w-full bg-transparent text-xs text-text-primary placeholder:text-text-muted focus:outline-none"
        />
        {busy && <Loader2 className="h-3.5 w-3.5 shrink-0 animate-spin text-text-muted" />}
      </div>
      {open && (
        <div className="absolute z-20 mt-1 max-h-56 w-full overflow-y-auto rounded-lg border border-border bg-card shadow-lg">
          {results.length === 0 ? (
            <div className="px-3 py-2 text-[11px] text-text-muted">No stops match</div>
          ) : (
            results.map((s) => (
              <button
                key={s.stop_id}
                onClick={() => {
                  onChange({
                    mode: 'stop',
                    stop_id: s.stop_id,
                    name: s.stop_name,
                    lat: s.lat,
                    lon: s.lon,
                  });
                  setOpen(false);
                }}
                className="block w-full px-3 py-2 text-left transition-colors hover:bg-card-hover"
              >
                <span className="block text-[11px] font-semibold text-text-primary">{s.stop_name}</span>
                {s.routes.length > 0 && (
                  <span className="mt-0.5 flex flex-wrap gap-1">
                    {s.routes.slice(0, 6).map((r) => (
                      <span key={r} className="rounded bg-card-hover px-1 py-px text-[9px] text-text-muted">
                        {r}
                      </span>
                    ))}
                  </span>
                )}
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
}

export default function TravelPanel({
  picks,
  onPicksChange,
  serviceDay,
  onItineraries,
  optimizerSettings,
}: Props) {
  const [mode, setMode] = useState<'depart_at' | 'arrive_by'>('depart_at');
  const [time, setTime] = useState('08:00');
  const [maxTransfers, setMaxTransfers] = useState(2);
  const [running, setRunning] = useState(false);
  const [optimizing, setOptimizing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TravelCompareResponse | null>(null);

  const setOrigin = useCallback(
    (p: TravelPoint | null) => onPicksChange((prev) => ({ ...prev, origin: p })),
    [onPicksChange]
  );
  const setDestination = useCallback(
    (p: TravelPoint | null) => onPicksChange((prev) => ({ ...prev, destination: p })),
    [onPicksChange]
  );

  const buildBody = useCallback(() => {
    const timeVal = labelToMin(time);
    return {
      origin: picks.origin!,
      destination: picks.destination!,
      [mode]: timeVal,
      max_transfers: maxTransfers,
      service_day: serviceDay,
      max_shift: optimizerSettings.max_shift,
      buffer_minutes: optimizerSettings.buffer_minutes,
      high_freq_cutoff: optimizerSettings.high_freq_cutoff,
      t_max: optimizerSettings.t_max,
      volume_mode: optimizerSettings.volume_mode,
      window_start: optimizerSettings.window_start,
      window_end: optimizerSettings.window_end,
      max_connections: optimizerSettings.max_connections,
      time_limit_seconds: optimizerSettings.time_limit_seconds,
      min_layover_minutes: optimizerSettings.min_layover_minutes,
    };
  }, [picks.origin, picks.destination, mode, time, maxTransfers, serviceDay, optimizerSettings]);

  const run = useCallback(async () => {
    if (!picks.origin || !picks.destination) {
      setError('Pick both an origin and a destination (search or click the map).');
      return;
    }
    setRunning(true);
    setOptimizing(true);
    setError(null);
    setResult(null);
    try {
      const body = buildBody();
      // Phase 1: baseline only (fast, ~1-2s)
      const baselineRes = await api.travelBaseline(body);
      setResult(baselineRes);
      setRunning(false);
      onItineraries({
        baseline: baselineRes.baseline,
        optimized: null,
        origin: baselineRes.origin,
        destination: baselineRes.destination,
      });
      // Phase 2: full comparison with optimizer (slow, ~60s first run)
      const fullRes = await api.travelCompare(body);
      setResult(fullRes);
      onItineraries({
        baseline: fullRes.baseline,
        optimized: fullRes.optimized,
        origin: fullRes.origin,
        destination: fullRes.destination,
      });
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      onItineraries(null);
    } finally {
      setRunning(false);
      setOptimizing(false);
    }
  }, [buildBody, onItineraries]);

  return (
    <div className="flex h-full flex-col gap-3 overflow-y-auto p-3">
      <section className="rounded-xl border border-border bg-card p-3">
        <div className="mb-2 flex items-center gap-2 text-xs font-bold text-text-primary">
          <Route className="h-4 w-4 text-accent" />
          Plan a journey
        </div>
        <p className="mb-2.5 text-[11px] leading-relaxed text-text-muted">
          See how long the same trip takes today versus the optimized schedule. Pick two stops or click the map.
        </p>

        <NewHereHint text="Tip: click the map to set your start or end point, or search for a stop by name." />

        <div className="mt-3 flex flex-col gap-2.5">
          <StopInput label="From" value={picks.origin} onChange={setOrigin} accent="origin" />
          <div className="flex justify-center">
            <ArrowRight className="h-3.5 w-3.5 text-text-muted" />
          </div>
          <StopInput
            label="To"
            value={picks.destination}
            onChange={setDestination}
            accent="destination"
          />

          {/* map-click target */}
          <div className="rounded-lg border border-dashed border-border bg-card-hover/50 px-2.5 py-2">
            <div className="flex items-center gap-1.5 text-[10px] text-text-muted">
              <MousePointerClick className="h-3.5 w-3.5 text-accent" />
              Clicking the map sets:
            </div>
            <div className="mt-1.5 flex overflow-hidden rounded-lg border border-border">
              {(['origin', 'destination'] as const).map((t) => (
                <button
                  key={t}
                  onClick={() => onPicksChange((prev) => ({ ...prev, nextPick: t }))}
                  className={`flex-1 px-2 py-1 text-[10px] font-semibold transition-colors ${
                    picks.nextPick === t
                      ? t === 'origin'
                        ? 'bg-optimized/15 text-optimized'
                        : 'bg-accent/15 text-accent'
                      : 'text-text-secondary hover:bg-card-hover'
                  }`}
                >
                  {t === 'origin' ? 'From' : 'To'}
                </button>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="flex flex-1 overflow-hidden rounded-lg border border-border">
              {(['depart_at', 'arrive_by'] as const).map((m) => (
                <button
                  key={m}
                  onClick={() => setMode(m)}
                  className={`flex-1 px-2 py-1.5 text-[10px] font-semibold transition-colors ${
                    mode === m ? 'bg-optimized/15 text-optimized' : 'text-text-secondary hover:bg-card-hover'
                  }`}
                >
                  {m === 'depart_at' ? 'Depart' : 'Arrive'}
                </button>
              ))}
            </div>
            <div className="flex items-center gap-1 rounded-lg border border-border bg-card-hover px-2 py-1">
              <Clock className="h-3.5 w-3.5 text-text-muted" />
              <input
                type="time"
                value={time}
                onChange={(e) => setTime(e.target.value || '08:00')}
                className="w-20 bg-transparent text-xs text-text-primary focus:outline-none"
              />
            </div>
          </div>

          <label className="flex flex-col gap-1">
            <span className="text-[10px] font-semibold uppercase tracking-wide text-text-muted">
              Max transfers
            </span>
            <select
              value={maxTransfers}
              onChange={(e) => setMaxTransfers(Number(e.target.value))}
              className="rounded-lg border border-border bg-card-hover px-2 py-1.5 text-xs text-text-primary focus:outline-none"
            >
              {[0, 1, 2, 3, 4].map((n) => (
                <option key={n} value={n}>
                  {n === 0 ? 'No transfers' : `${n} transfer${n > 1 ? 's' : ''}`}
                </option>
              ))}
            </select>
          </label>

          <button
            onClick={run}
            disabled={running || !picks.origin || !picks.destination}
            className="inline-flex items-center justify-center gap-2 rounded-lg bg-optimized px-3 py-2 text-xs font-bold text-bg transition-colors hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40"
          >
            {running ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" /> Finding baseline route…
              </>
            ) : (
              <>
                <Zap className="h-4 w-4" /> Compare trips
              </>
            )}
          </button>
        </div>

        {error && (
          <div className="mt-2 rounded-lg border border-danger/40 bg-danger/10 px-3 py-2 text-[11px] text-danger">
            {error}
          </div>
        )}
      </section>

      {optimizing && result?.baseline && (
        <div className="animate-pulse rounded-xl border border-optimized/30 bg-optimized/5 p-4 text-[11px] text-text-muted">
          <span className="flex items-center gap-2">
            <Loader2 className="h-3.5 w-3.5 animate-spin text-optimized" />
            <span className="font-semibold text-optimized">Optimized schedule loading…</span>
            The optimizer runs the full network re-sync (~1 min first time, instant after).
          </span>
        </div>
      )}

      {result && result.baseline && !running && (
        <>
          <section
            className={`rounded-xl border p-3 ${
              result.savings_minutes != null && result.savings_minutes > 0
                ? 'border-optimized/50 bg-optimized/10'
                : 'border-border bg-card'
            }`}
          >
            <div className="flex items-center gap-2 text-xs font-bold">
              <Timer
                className={`h-4 w-4 ${
                  result.savings_minutes != null && result.savings_minutes > 0
                    ? 'text-optimized'
                    : 'text-text-muted'
                }`}
              />
              {optimizing ? (
                <span className="text-text-secondary">
                  Comparing against the optimized schedule…
                </span>
              ) : result.savings_minutes != null && result.savings_minutes > 0 ? (
                <span className="text-optimized">
                  Riders save ~{result.savings_minutes.toFixed(1)} min
                </span>
              ) : result.savings_minutes != null && result.savings_minutes < 0 ? (
                <span className="text-bottleneck">
                  Optimized schedule ~{Math.abs(result.savings_minutes).toFixed(1)} min slower
                  for this trip
                </span>
              ) : (
                <span className="text-text-secondary">
                  No time difference for this trip (today vs optimized)
                </span>
              )}
            </div>
            <p className="mt-1.5 text-[10px] leading-snug text-text-muted">
              {result.baseline == null && result.optimized == null ? (
                <>No route found on either schedule for this origin/destination/time.</>
              ) : result.optimizer ? (
                <>
                  Leaving {result.origin.name ?? 'origin'} at {minToLabel(result.time)} ·{' '}
                  {result.optimizer.offsets_count} of {result.optimizer.movable_routes} route
                  schedules shifted · network avg wait {result.optimizer.baseline_avg_wait.toFixed(1)}→
                  {result.optimizer.optimized_avg_wait.toFixed(1)} min.
                </>
              ) : (
                <>
                  Leaving {result.origin.name ?? 'origin'} at {minToLabel(result.time)}
                </>
              )}
            </p>
          </section>

          <div className="flex flex-col gap-3">
            {result.baseline && (
              <ItineraryCard title="Today's schedule" accent="text-text-muted" itin={result.baseline} />
            )}
            {result.optimized && (
              <ItineraryCard title="Optimized schedule" accent="text-optimized" itin={result.optimized} />
            )}
            <div className="flex items-center gap-1.5 rounded-lg bg-card-hover px-3 py-2 text-[10px] text-text-muted">
              <Sparkles className="h-3 w-3 text-accent" />
              Blue line on the map = optimized route; grey = today's route.
            </div>
          </div>
        </>
      )}
    </div>
  );
}
