/**
 * Before/after mini-map: a single route, today vs its proposed trunk + feeder
 * split, in a small SVG (no tiles). Today's routing is a thin gray dashed
 * line; the proposed trunk is the solid colored line and the feeders are
 * dashed in the same route color — matching the full Trunk & feeder map's
 * legend. Coordinates are WGS84 (lon, lat) with a cos(lat) aspect fix so the
 * shape matches what the Leaflet map shows.
 */

interface Props {
  /** WGS84 (lon, lat) vertices of today's routing. */
  coords: [number, number][];
  /** WGS84 (lon, lat) vertices of the proposed trunk. */
  trunkCoords: [number, number][];
  /** WGS84 (lon, lat) vertices of each proposed feeder. */
  branchCoords: [number, number][][];
  /** Route color (same one the big map uses). */
  color: string;
}

const W = 260;
const H = 130;

function toPath(
  coords: [number, number][],
  pt: (lon: number, lat: number) => [number, number]
): string {
  return coords
    .map(([lon, lat], i) => {
      const [x, y] = pt(lon, lat);
      return `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');
}

export default function BeforeAfterMiniMap({
  coords,
  trunkCoords,
  branchCoords,
  color,
}: Props) {
  const all = [coords, trunkCoords, ...branchCoords].filter((c) => c.length > 1);
  if (all.length === 0) return null;

  const lons = all.flatMap((c) => c.map((p) => p[0]));
  const lats = all.flatMap((c) => c.map((p) => p[1]));
  const minLon = Math.min(...lons);
  const maxLon = Math.max(...lons);
  const minLat = Math.min(...lats);
  const maxLat = Math.max(...lats);

  // Aspect-corrected fit (Web-Mercator-ish): compress longitudes by cos(lat)
  // so a north-south street is the same apparent length as an east-west one.
  const midLat = (minLat + maxLat) / 2;
  const kx = Math.cos((midLat * Math.PI) / 180) || 1e-9;
  const spanX = (maxLon - minLon) * kx || 1e-9;
  const spanY = maxLat - minLat || 1e-9;
  const pad = 10;
  const scale = Math.min((W - pad * 2) / spanX, (H - pad * 2) / spanY);
  const ox = (W - spanX * scale) / 2;
  const oy = (H - spanY * scale) / 2;
  const pt = (lon: number, lat: number): [number, number] => [
    ox + (lon - minLon) * kx * scale,
    oy + (maxLat - lat) * scale,
  ];

  return (
    <svg
      viewBox={`0 0 ${W} ${H}`}
      role="img"
      aria-label="Before and after route map"
      className="h-auto w-full rounded-md bg-bg ring-1 ring-border"
      preserveAspectRatio="xMidYMid meet"
    >
      {/* Today's winding routing */}
      <path
        d={toPath(coords, pt)}
        fill="none"
        stroke="#71717A"
        strokeWidth={1.2}
        strokeDasharray="2.5 2.5"
        opacity={0.6}
      />
      {/* Proposed feeders (dashed, route color) */}
      {branchCoords.map((b, i) =>
        b.length > 1 ? (
          <path
            key={`b${i}`}
            d={toPath(b, pt)}
            fill="none"
            stroke={color}
            strokeWidth={1.6}
            strokeDasharray="5 3"
            opacity={0.9}
          />
        ) : null
      )}
      {/* Proposed trunk (solid, route color) */}
      {trunkCoords.length > 1 ? (
        <path d={toPath(trunkCoords, pt)} fill="none" stroke={color} strokeWidth={2.6} />
      ) : null}
    </svg>
  );
}
