import { useEffect, useMemo, useRef, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import BasemapPicker from './BasemapPicker';
import { basemapById, defaultBasemapId } from '../lib/basemaps';
import { circuityColor } from '../lib/circuityColor';
import { api } from '../lib/api';
import type { CircuityGeoJSON, CorridorGap, TransferNode, EquityReport } from '../types';

/**
 * Main interactive map built on Leaflet (pure DOM — no WebGL required, so it
 * works on ARM64 / VM / remote-desktop browsers where WebGL maps go black).
 *
 * Basemap: swappable via the top-right picker (Humanitarian HOT by default,
 * free + keyless). Route/node overlays sit above real roads instead of a grey
 * void:
 *   https://tile-a.openstreetmap.fr/hot
 *   (CARTO Positron was retired behind a key; the picker lists keyless sources.)
 *
 * The route / split / node layers are drawn from the route GeoJSON itself, so
 * they render even if the tile host is unreachable. If tiles can't load the
 * map just shows routes on a light background.
 */

const CENTER: [number, number] = [43.589, -79.6441]; // Leaflet uses [lat, lng]
const INITIAL_ZOOM = 11;
// Nodes only appear once the user zooms in past the city overview zoom.
const NODE_MIN_ZOOM = 13;
// Distinct color + dash used to draw routes that run only one way in the
// current time period (e.g. AM-rush-only inbound routes).
const ONE_WAY_COLOR = '#E040FB';

// Direction colors for the optimizer re-phase overlay: routes the solver
// moved EARLIER draw blue, routes moved LATER draw amber, weight scaled by
// the offset magnitude so the map reads at a glance which routes the solver
// re-phased and by how much.
const SHIFT_EARLIER_COLOR = '#3b82f6';
const SHIFT_LATER_COLOR = '#f59e0b';

// Fallback amber for proposed trunk/branch lines (only used if a route is
// somehow missing from the palette).
export const PROPOSED_DEFAULT_COLOR = '#FFB300';

// Muted grey for candidate proposals in focus mode (the map's calm default):
// every unselected trunk + feeder draws in this single tone so the view reads
// as one organized set of candidates instead of a rainbow. Selecting a route
// swaps its pieces to the route's own hue.
export const PROPOSED_MUTED_COLOR = '#8F97A3';

// Golden-angle hue stepping: every proposed route gets its own hue, keeping
// arbitrary counts well-spaced (trunk and branch share the route's hue, so a
// split reads as one route). Shared with the trunk & feeder panel so row
// badges match the map's colors exactly.
const ROUTE_HUE_STEP = 137.508;
export function routePalette(routeNames: string[]): Map<string, string> {
  const sorted = [...routeNames].sort((a, b) => {
    const na = Number.parseInt(a, 10);
    const nb = Number.parseInt(b, 10);
    if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
    return a.localeCompare(b);
  });
  const m = new Map<string, string>();
  sorted.forEach((r, i) => {
    const hue = Math.round((i * ROUTE_HUE_STEP) % 360);
    m.set(r, `hsl(${hue}, 70%, 56%)`);
  });
  return m;
}

export type MapEngine = 'auto' | 'leaflet' | 'svg';

/** A polyline to draw on top of the network (e.g. a planned journey). */
export interface TravelLine {
  id: string;
  label: string;
  color: string;
  dashArray?: string;
  weight?: number;
  points: [number, number][]; // [lat, lon]
}

export interface TravelMarker {
  id: string;
  label: string;
  color: string;
  lat: number;
  lon: number;
}

/** One route the optimizer re-phased (offset != 0), for the shift overlay. */
export interface OptimizeShift {
  route_short_name: string;
  offset_minutes: number;
}

/**
 * Stroke widths scale with zoom. At city-wide zoom (11) fifty-odd overlapping
 * routes with fat 5px casings blend into ribbon spaghetti; each line thins as
 * you zoom out so the network reads as lines, and fattens at street zoom
 * where there is room for the detail.
 */
function routeStroke(zoom: number) {
  if (zoom >= 15) return { line: 4, casing: 6, casingOpacity: 0.55 };
  if (zoom >= 13) return { line: 3, casing: 4.5, casingOpacity: 0.45 };
  if (zoom >= 12) return { line: 2.4, casing: 3.6, casingOpacity: 0.38 };
  return { line: 2, casing: 3, casingOpacity: 0.3 };
}

/** Legend chips: representative circuity values, colored by the real scale. */
const LEGEND_STOPS = [
  { c: 1.05, label: 'direct' },
  { c: 1.5, label: 'winds a bit' },
  { c: 1.8, label: 'very winding' },
  { c: 3.2, label: 'severe' },
];

interface Props {
  circuity: CircuityGeoJSON | null;
  nodes: TransferNode[];
  showRoutes: boolean;
  showSplits: boolean;
  showNodes: boolean;
  showOneWay?: boolean;
  highlightedRoute?: string | null;
  engine?: MapEngine;
  travelLines?: TravelLine[];
  travelMarkers?: TravelMarker[];
  /** When set, a map click emits (lat, lon) instead of doing nothing. */
  onMapPick?: (lat: number, lon: number) => void;
  pickActive?: boolean;
  /** Selected Route-gaps seam: draws its corridor stops + terminal on the map. */
  corridorSeam?: CorridorGap | null;
  /** Routes the optimizer re-phased, with their offsets. When non-empty the
   * base network dims and each moved route draws in a direction color (blue =
   * earlier, amber = later) with an offset badge — the "what did the solver
   * change" view, without needing the travel planner. */
  optimizeShifts?: OptimizeShift[];
  /** Draw every proposed trunk + branch with route-number badges, dimming the
   * current network so the proposed one reads as a single redesign. */
  showProposedNetwork?: boolean;
}

/** Bearing (degrees, 0 = north, clockwise) from point A to point B. */
function bearingDeg(a: [number, number], b: [number, number]): number {
  const toRad = Math.PI / 180;
  const lat1 = a[1] * toRad;
  const lat2 = b[1] * toRad;
  const dLon = (b[0] - a[0]) * toRad;
  const y = Math.sin(dLon) * Math.cos(lat2);
  const x =
    Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLon);
  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
}

/**
 * Apply the split layer's mode-aware styling to every polyline.
 *
 * Focus mode (showAll = false): unselected proposals draw in a single muted
 * grey (thin, translucent) so the map reads as one calm set of candidates;
 * the selected route pops in its own hue with trunk solid + feeders dashed.
 * Show-all mode: every proposal draws in its own hue; the selected route
 * pops via weight. Kept as one helper so the layer is styled the same right
 * after (re)building it and on every selection / mode change.
 */
function styleSplitLayer(
  layer: L.GeoJSON,
  showAll: boolean,
  highlightedRoute: string | null
) {
  layer.eachLayer((l) => {
    const props = (l as L.Polyline).feature?.properties as
      | { route?: string; part?: string; color?: string }
      | undefined;
    if (!props?.route) return;
    const branch = props.part === 'branch';
    const color = props.color ?? PROPOSED_DEFAULT_COLOR;
    const hl = highlightedRoute != null && props.route === highlightedRoute;
    if (showAll) {
      (l as L.Path).setStyle({
        color,
        weight: hl ? (branch ? 5 : 7) : branch ? 3.5 : 5,
        opacity: highlightedRoute != null ? (hl ? 1 : 0.55) : 1,
        dashArray: branch ? '6 5' : undefined,
      });
      return;
    }
    if (hl) {
      (l as L.Path).setStyle({
        color,
        weight: branch ? 3.5 : 5,
        opacity: 1,
        dashArray: branch ? '6 5' : undefined,
      });
    } else {
      (l as L.Path).setStyle({
        color: PROPOSED_MUTED_COLOR,
        weight: branch ? 2.5 : 3,
        opacity: 0.4,
        dashArray: branch ? '6 5' : undefined,
      });
    }
  });
}

/** Build a leaflet DivIcon: a small arrow rotated to a heading. */
function directionIcon(deg: number, color = ONE_WAY_COLOR): L.DivIcon {
  const html = `<svg width="16" height="16" viewBox="0 0 16 16" style="transform:rotate(${deg}deg)">
    <path d="M8 2 L14 8 L8 14 M14 8 H0" stroke="${color}" stroke-width="2" fill="none"
      stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
  return L.divIcon({ html, className: 'route-direction-arrow', iconSize: [16, 16], iconAnchor: [8, 8] });
}

export default function MapView({
  circuity,
  nodes,
  showRoutes,
  showSplits,
  showNodes,
  showOneWay = false,
  highlightedRoute,
  engine = 'auto',
  travelLines = [],
  travelMarkers = [],
  onMapPick,
  pickActive = false,
  showProposedNetwork = false,
  optimizeShifts = [],
  corridorSeam = null,
}: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const routeLayerRef = useRef<L.GeoJSON | null>(null);
  const splitLayerRef = useRef<L.GeoJSON | null>(null);
  const nodeLayerRef = useRef<L.LayerGroup | null>(null);
  const oneWayLayerRef = useRef<L.LayerGroup | null>(null);
  const travelLayerRef = useRef<L.LayerGroup | null>(null);
  const seamLayerRef = useRef<L.LayerGroup | null>(null);
  const shiftLayerRef = useRef<L.LayerGroup | null>(null);
  const proposedLabelLayerRef = useRef<L.LayerGroup | null>(null);

  // One distinct hue per proposed route (trunk + branch share it).
  const proposalColors = useMemo(
    () =>
      routePalette(
        (circuity?.features ?? [])
          .filter((f) => f.properties.flagged && f.properties.proposed_split)
          .map((f) => f.properties.route_short_name)
      ),
    [circuity]
  );
const [tileNote, setTileNote] = useState<string | null>(null);
// Hover-to-isolate: pointing at a route dims the rest of the network so it
// can be traced without clicking. Explicit panel selection overrides it.
const [hoverRoute, setHoverRoute] = useState<string | null>(null);
// Zoom level drives routeStroke(); synced from the map's zoomend below.
const [zoomLevel, setZoomLevel] = useState(INITIAL_ZOOM);
// Active basemap (defaults from localStorage, updated by the picker).
const [basemapId, setBasemapId] = useState(defaultBasemapId);
const basemap = basemapById(basemapId);
const tileLayerRef = useRef<L.TileLayer | null>(null);

// Ward equity overlay — scores derive from the equity report in the effect
// below; the map layer colors from wardScores only.
const [wardBoundaries, setWardBoundaries] = useState<GeoJSON.FeatureCollection<GeoJSON.Polygon | GeoJSON.MultiPolygon> | null>(null);
const [wardScores, setWardScores] = useState<Record<string, number>>({});
const [showWardScores, setShowWardScores] = useState(false);
const wardLayerRef = useRef<L.GeoJSON | null>(null);

  const useLeaflet = engine !== 'svg';

  // ---- initialize the Leaflet map once --------------------------------
  useEffect(() => {
    if (!containerRef.current || !useLeaflet) return;
    const map = L.map(containerRef.current, {
      center: CENTER,
      zoom: INITIAL_ZOOM,
    });
    map.attributionControl.setPrefix(false);
    // Track zoom so stroke weights can scale (see routeStroke).
    map.on('zoomend', () => setZoomLevel(map.getZoom()));

    // init empty overlay layers
    const routeLayer = L.geoJSON(null as unknown as GeoJSON.GeoJsonObject, {
      style: () => ({ color: '#00E676', weight: 2, opacity: 0.85 }),
    });
    routeLayer.addTo(map);
    // Trunk draws solid and heavier, branches dashed and lighter — the route's
    // own hue ties the whole family together while the weight/dash keeps the
    // main line unmistakable.
    // Base style is applied per-feature by the split rebuild effect below
    // (focus mode: muted grey unless selected; show-all mode: route hues).
    const splitLayer = L.geoJSON(null as unknown as GeoJSON.GeoJsonObject, {
      style: () => ({ color: PROPOSED_MUTED_COLOR, weight: 3, opacity: 0.4 }),
    });
    splitLayer.addTo(map);
    const nodeLayer = L.layerGroup();
    nodeLayer.addTo(map);
    const oneWayLayer = L.layerGroup();
    oneWayLayer.addTo(map);
    const travelLayer = L.layerGroup();
    travelLayer.addTo(map);
const seamLayer = L.layerGroup();
seamLayer.addTo(map);
const shiftLayer = L.layerGroup();
shiftLayer.addTo(map);
const proposedLabelLayer = L.layerGroup();
proposedLabelLayer.addTo(map);
// Ward equity layer (GeoJSON)
const wardLayer = L.geoJSON(null, {
  style: (feature) => {
    const wardId = feature?.properties?.WARD as string | undefined;
    const score = wardScores[wardId ?? ''];
    // Color scale: blue (negative/savings) to white (neutral) to red (positive/cost)
    // Using a diverging color scheme similar to EquityPanel
    let color;
    if (score === 0) {
      color = '#f0f0f0'; // neutral
    } else if (score < 0) {
      // Negative scores (time savings) - blue scale (dodger blue)
      color = `rgb(30, 144, 255)`;
    } else {
      // Positive scores (time costs) - red scale (tomato red)
      color = `rgb(255, 99, 71)`;
    }
    return {
      color: color,
      weight: 1,
      opacity: 0.7,
      fillColor: color,
      fillOpacity: 0.4
    };
  }
});
wardLayer.addTo(map);

routeLayerRef.current = routeLayer;
splitLayerRef.current = splitLayer;
nodeLayerRef.current = nodeLayer;
oneWayLayerRef.current = oneWayLayer;
travelLayerRef.current = travelLayer;
seamLayerRef.current = seamLayer;
shiftLayerRef.current = shiftLayer;
proposedLabelLayerRef.current = proposedLabelLayer;
wardLayerRef.current = wardLayer;
mapRef.current = map;

    // keep Leaflet sized correctly inside the flex layout.
    // The window listener misses container resizes that React layout causes
    // without a window resize event (sidebar / panel switches, engine
    // switches) - a ResizeObserver on the container closes that gap.
    const onResize = () => map.invalidateSize();
    window.addEventListener('resize', onResize);
    const t = window.setTimeout(() => map.invalidateSize(), 120);
    const ro = new ResizeObserver(onResize);
    ro.observe(containerRef.current);

    return () => {
      window.clearTimeout(t);
      window.removeEventListener('resize', onResize);
      ro.disconnect();
      map.remove();
      // Null every layer ref so the drawing effects' own `if (!layer) return;`
      // guards bail out cleanly when the engine switches to SVG (otherwise they
      // hold stale detached layers and call addTo() on a dead map: null.addLayer).
      mapRef.current = null;
      routeLayerRef.current = null;
      splitLayerRef.current = null;
      nodeLayerRef.current = null;
      oneWayLayerRef.current = null;
      travelLayerRef.current = null;
      seamLayerRef.current = null;
      shiftLayerRef.current = null;
      proposedLabelLayerRef.current = null;
      tileLayerRef.current = null;
    };
  }, [useLeaflet]);

  // Sync basemap choice with the shared picker. Whatever component changes
  // the basemap broadcasts an event; every mounted map adopts it so switching
  // in one view updates the rest without refetching.
  useEffect(() => {
    const handler = (e: Event) => {
      const id = (e as CustomEvent<string>).detail;
      if (id) setBasemapId(id);
    };
    window.addEventListener('miway:basemap', handler);
    return () => window.removeEventListener('miway:basemap', handler);
  }, []);

  // ---- basemap tiles (swappable via the picker) ----------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !useLeaflet) return;
    // Swap away the old layer if we already have one, then draw the chosen
    // style. keepInView avoids a jarring recentre; noRedraw=False reloads.
    const prev = tileLayerRef.current;
    let errCount = 0;
    const tiles = L.tileLayer(basemap.url, {
      subdomains: basemap.subdomains ?? 'abcd',
      maxZoom: 20,
      attribution: basemap.attribution,
    });
    tiles.on('tileerror', () => {
      errCount += 1;
      if (errCount >= 4) setTileNote('Base tiles unreachable — showing routes only');
    });
    tiles.addTo(map);
    tileLayerRef.current = tiles;
    if (prev && map.hasLayer(prev)) map.removeLayer(prev);
    return () => {
      if (map.hasLayer(tiles)) map.removeLayer(tiles);
      if (tileLayerRef.current === tiles) tileLayerRef.current = null;
    };
  }, [basemap, useLeaflet]);

   // Fetch equity report data (same as EquityPanel)
   useEffect(() => {
     if (!useLeaflet) return;

     let cancelled = false;

     const loadEquityData = async () => {
       try {
         // Try the on-the-fly compute endpoint first (uses latest optimizer run).
         // Falls back to the file-based report if no optimization has been run.
         let d: EquityReport;
         try {
           d = await api.equityCompute();
         } catch {
           d = await api.equityReport();
         }
        if (!cancelled) {
          // Extract ward scores from the equity report
           if (d?.wards?.rows) {
             const scores: Record<string, number> = {};
             for (const ward of d.wards.rows) {
               scores[ward.ward] = ward.delta_minutes;
             }
             setWardScores(scores);
           }
         }
       } catch (e) {
         console.error('Failed to load equity data:', e);
         // Silently fail - we don't want to spam the UI with errors for an optional overlay
       }
     };

     void loadEquityData();

     return () => {
       cancelled = true;
     };
   }, [useLeaflet]);

   // Load ward boundaries GeoJSON
   useEffect(() => {
     if (!useLeaflet) return;

     let cancelled = false;

     const loadWardBoundaries = async () => {
       try {
         const response = await fetch('/app/data/downloads/mississauga_ward_boundaries.geojson');
         if (!response.ok) {
           throw new Error(`Failed to load ward boundaries: ${response.status}`);
         }
         const geojson = await response.json();
         if (!cancelled && geojson.type === 'FeatureCollection') {
           setWardBoundaries(geojson);
         }
       } catch (e) {
         console.warn('Could not load ward boundaries GeoJSON:', e);
         // Silently fail - ward boundaries are optional for the map
       }
     };

     void loadWardBoundaries();

     return () => {
       cancelled = true;
     };
   }, [useLeaflet]);

  // ---- route overlay (GeoJSON, styled by circuity) --------------------
  // Each route draws twice: a dark casing underneath (a thin slate outline,
  // barely visible) plus the vivid circuity-colored line on top. The casing
  // keeps every route legible on light/muted basemaps (e.g. Humanitarian),
  // where thin colored lines — especially the mid-gradient yellow — wash out.
  // Both polylines carry the route's `.feature` so the highlight / dimming
  // effect below styles them together; the casing is flagged `isCasing`.
  useEffect(() => {
    const layer = routeLayerRef.current;
    if (!layer || !circuity) return;
    const stroke = routeStroke(zoomLevel);
    layer.clearLayers();
    circuity.features.forEach((f) => {
      const coords = f.geometry.coordinates;
      if ((coords as Array<unknown>).length < 2) return;
      const latlngs = coords.map(([lon, lat]) => [lat, lon] as L.LatLngTuple);

      const casing = L.polyline(latlngs, {
        color: '#233244',
        weight: stroke.casing,
        opacity: stroke.casingOpacity,
        interactive: false,
      });
      (casing as unknown as { feature?: GeoJSON.Feature }).feature = f;
      (casing as unknown as { isCasing?: boolean }).isCasing = true;
      casing.addTo(layer);

      const line = L.polyline(latlngs, {
        color: circuityColor(f.properties.circuity),
        weight: stroke.line,
        opacity: 0.95,
      });
      (line as unknown as { feature?: GeoJSON.Feature }).feature = f;
      line.bindPopup(`<strong>Route ${f.properties.route_short_name}</strong>`);
      line.bindTooltip(`Route ${f.properties.route_short_name}`, {
        sticky: true,
        direction: 'top',
        opacity: 0.9,
      });
      line.on('mouseover', () => setHoverRoute(f.properties.route_short_name));
      line.on('mouseout', () => setHoverRoute(null));
      line.addTo(layer);
    });
  }, [circuity, useLeaflet, zoomLevel]);

  useEffect(() => {
    const layer = routeLayerRef.current;
    if (!layer) return;
    if (showRoutes) {
      if (!mapRef.current?.hasLayer(layer)) layer.addTo(mapRef.current!);
    } else {
      mapRef.current?.removeLayer(layer);
    }
  }, [showRoutes, useLeaflet]);

  // ---- split branch overlay -------------------------------------------
  // In focus mode (showProposedNetwork off) unselected proposals draw muted
  // grey and only the selected route shows its own hue, badges and junction
  // dots — the map stays calm and each route is read one at a time. In
  // show-all mode every proposal draws in its own hue with badges.
  const isSelected = (route: string) =>
    highlightedRoute != null && highlightedRoute === route;

  useEffect(() => {
    const layer = splitLayerRef.current;
    if (!layer || !circuity) return;
    layer.clearLayers();
    const features: GeoJSON.Feature[] = [];
    circuity.features.forEach((f) => {
      const p = f.properties;
      if (p.flagged && p.proposed_split) {
        const color = proposalColors.get(p.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
        features.push({
          type: 'Feature',
          properties: { route: p.route_short_name, part: 'trunk', color },
          geometry: {
            type: 'LineString',
            coordinates: p.proposed_split.trunk_geometry as [number, number][],
          },
        });
        p.proposed_split.branches.forEach((b, i) => {
          features.push({
            type: 'Feature',
            properties: { route: p.route_short_name, part: 'branch', branchIndex: i, color },
            geometry: { type: 'LineString', coordinates: b.geometry as [number, number][] },
          });
        });
      }
    });
    if (features.length) layer.addData({ type: 'FeatureCollection', features } as GeoJSON.GeoJsonObject);

    // Apply the mode-aware style immediately after (re)building the layer, so
    // a fresh circuity load is never left in the wrong style.
    styleSplitLayer(layer, showProposedNetwork, highlightedRoute ?? null);

    // Junction dots for corridor splices: the route leaves the donor corridor
    // at the first point and rejoins it at the second (the branch's endpoints
    // are exactly those two junctions). Hover for the stop name. In focus
    // mode only the selected route's dots draw, so the map stays uncluttered.
    circuity.features.forEach((f) => {
      const p = f.properties;
      const split = p.proposed_split;
      if (!p.flagged || !split?.splice_junctions?.length) return;
      if (!showProposedNetwork && !isSelected(p.route_short_name)) return;
      const color = proposalColors.get(p.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
      split.splice_junctions.forEach((j, k) => {
        const circle = L.circleMarker([j.lat, j.lon], {
          radius: 7,
          color: '#ffffff',
          weight: 2.5,
          fillColor: color,
          fillOpacity: 1,
        });
        circle.bindTooltip(
          `<strong>Route ${p.route_short_name}</strong> — ${k === 0 ? 'leaves' : 'rejoins'} Route ${split.donor_route}'s routing<br/>${j.label}`,
          { direction: 'top' }
        );
        circle.addTo(layer);
      });
    });
  }, [circuity, proposalColors, showProposedNetwork, highlightedRoute, useLeaflet]);

  useEffect(() => {
    const layer = splitLayerRef.current;
    if (!layer) return;
    if (showSplits) {
      if (!mapRef.current?.hasLayer(layer)) layer.addTo(mapRef.current!);
    } else {
      mapRef.current?.removeLayer(layer);
    }
  }, [showSplits, useLeaflet]);

  // ---- one-way (single direction) route overlay ------------------------
  useEffect(() => {
    const group = oneWayLayerRef.current;
    if (!group) return;
    group.clearLayers();
    if (!showOneWay || !circuity) return;

    circuity.features.forEach((f) => {
      if (!f.properties.one_way) return;
      const coords = f.geometry.coordinates as [number, number][];
      if (coords.length < 2) return;
      const latlngs = coords.map(([lon, lat]) => [lat, lon] as L.LatLngTuple);

      const line = L.polyline(latlngs, {
        color: ONE_WAY_COLOR,
        weight: 3,
        dashArray: '8 6',
        opacity: 0.95,
      });
      line.bindPopup(
        `<strong>Route ${f.properties.route_short_name}</strong><br/>Runs one way only in this period`
      );
      line.addTo(group);

      // direction arrows at evenly spaced points along the shape
      const step = Math.max(1, Math.floor(latlngs.length / 6));
      for (let i = 0; i < latlngs.length - 1; i += step) {
        const a = coords[i];
        const b = coords[Math.min(i + 1, coords.length - 1)];
        const mid: [number, number] = [
          (latlngs[i][0] + latlngs[i + 1][0]) / 2,
          (latlngs[i][1] + latlngs[i + 1][1]) / 2,
        ];
        L.marker(mid, {
          icon: directionIcon(bearingDeg(a, b)),
          interactive: false,
        }).addTo(group);
      }
    });
  }, [circuity, showOneWay, useLeaflet]);

  // ---- transfer stop nodes --------------------------------------------
  useEffect(() => {
    const group = nodeLayerRef.current;
    if (!group) return;
    group.clearLayers();
    nodes.forEach((n) => {
      const color = n.friction_score > 30 ? '#FF5252' : n.friction_score > 20 ? '#FFB300' : '#00E676';
      // Small dots, visible only once the user zooms in past the overview zoom.
      const radius = 2 + n.friction_score * 0.12;
      const marker = L.circleMarker([n.lat, n.lon], {
        radius,
        color: '#1f2937',
        weight: 1,
        fillColor: color,
        fillOpacity: 0.95,
      });
      marker.bindPopup(
        `<strong>${n.stop_name}</strong><br/>Routes: ${n.routes.join(', ')}<br/>Friction: ${n.friction_score.toFixed(1)} / 50`
      );
      marker.addTo(group);
    });
  }, [nodes, useLeaflet]);

  useEffect(() => {
    const group = nodeLayerRef.current;
    const map = mapRef.current;
    if (!group || !map) return;

    const sync = () => {
      const visible = showNodes && map.getZoom() >= NODE_MIN_ZOOM;
      if (visible) {
        if (!map.hasLayer(group)) group.addTo(map);
      } else {
        map.removeLayer(group);
      }
    };

    sync();
    map.on('zoomend', sync);
    return () => {
      map.off('zoomend', sync);
    };
  }, [showNodes, useLeaflet]);

  // ---- highlight a specific route -------------------------------------
  useEffect(() => {
    const layer = routeLayerRef.current;
    if (!layer) return;
    // Hover isolates gently (0.3) so a stray mouse pass never blanks the map;
    // an explicit panel selection isolates hard (0.12) and always wins.
    const focusRoute = highlightedRoute ?? hoverRoute;
    const hoverOnly = highlightedRoute == null && hoverRoute != null;
    const stroke = routeStroke(zoomLevel);
    // In proposed-network mode the current network no longer exists as drawn:
    // every route with a proposal is replaced by its trunk + feeder lines, and
    // the rest of today's network fades away too, so the map shows only the
    // redesigned network. Toggle the view off to compare with today's routes.
    layer.eachLayer((l) => {
      const cast = l as L.Path & {
        feature?: { properties?: { route_short_name?: string } };
        isCasing?: boolean;
      };
      const isCasing = !!cast.isCasing;
      const props = cast.feature?.properties;
      const route = props?.route_short_name;
      if (route == null) return;
      if (showProposedNetwork) {
        cast.setStyle({ opacity: 0 });
        return;
      }
      // Optimizer re-phase view: the whole base network steps back and the
      // shift overlay carries the moved routes, so only it should pop.
      if (optimizeShifts.length > 0) {
        cast.setStyle({ weight: isCasing ? stroke.casing : stroke.line, opacity: 0.08 });
        return;
      }
      const hl = focusRoute != null && route === focusRoute;
      if (isCasing) {
        // Casing dims a touch when unselected so the vivid line still leads;
        // it disappears only when the map is focusing on a single route.
        cast.setStyle({
          weight: stroke.casing,
          opacity: focusRoute != null ? (hl ? 0.6 : 0.15) : stroke.casingOpacity,
        });
        return;
      }
      cast.setStyle({
        weight: hl ? stroke.line + 1 : stroke.line,
        opacity: focusRoute != null ? (hl ? 1 : hoverOnly ? 0.3 : 0.12) : 0.95,
      });
    });
  }, [highlightedRoute, hoverRoute, zoomLevel, showProposedNetwork, optimizeShifts, circuity, useLeaflet]);

  // ---- proposed split emphasis (selected route pops) ------------------
  useEffect(() => {
    const layer = splitLayerRef.current;
    if (!layer) return;
    styleSplitLayer(layer, showProposedNetwork, highlightedRoute ?? null);
  }, [showProposedNetwork, highlightedRoute, circuity, useLeaflet]);

  // ---- proposed-network route-number badges ---------------------------
  // Show-all mode labels every proposal; focus mode labels only the selected
  // route (the panel explains it in color next to the map), keeping the calm
  // view free of badge clutter.
  useEffect(() => {
    const group = proposedLabelLayerRef.current;
    const map = mapRef.current;
    if (!group || !map || !circuity) return;
    group.clearLayers();
    // Badges only make sense when the proposed split lines are actually drawn
    // on the map — gating on the same `showSplits` flag keeps a plain route
    // highlight (Explore's "Highlight a route", Home jump-ins, optimizer
    // results) from silently rendering unexplained 35 / 35A badges.
    if (!showSplits || (!showProposedNetwork && highlightedRoute == null)) {
      map.removeLayer(group);
      return;
    }
    circuity.features.forEach((f) => {
      const p = f.properties;
      if (!p.flagged || !p.proposed_split) return;
      if (!showProposedNetwork && p.route_short_name !== highlightedRoute) return;
      const color = proposalColors.get(p.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
      // Trunk badge: solid fill in the route's color (main line).
      const parts: { label: string; color: string; coords: [number, number][]; solid: boolean }[] = [
        { label: p.route_short_name, color, coords: p.proposed_split.trunk_geometry, solid: true },
      ];
      // Feeder badges: outlined, lettered (36A, 36B, ...).
      p.proposed_split.branches.forEach((b, i) => {
        parts.push({
          label: `${p.route_short_name}${String.fromCharCode(65 + i)}`,
          color,
          coords: b.geometry,
          solid: false,
        });
      });
      parts.forEach(({ label, color, coords, solid }) => {
        if (coords.length < 2) return;
        const mid = coords[Math.floor(coords.length / 2)];
        const html = solid
          ? `<div class="proposed-route-badge-solid" style="background:${color}">${label}</div>`
          : `<div class="proposed-route-badge-inner" style="border-color:${color};color:${color}">${label}</div>`;
        const icon = L.divIcon({ className: 'proposed-route-badge', html, iconSize: [0, 0] });
        L.marker([mid[1], mid[0]], { icon, interactive: false }).addTo(group);
      });
    });
    if (!map.hasLayer(group)) group.addTo(map);
  }, [circuity, showProposedNetwork, showSplits, proposalColors, highlightedRoute, useLeaflet]);

  // ---- planned journey overlay (travel compare) -------------------------
  useEffect(() => {
    const group = travelLayerRef.current;
    const map = mapRef.current;
    if (!group || !map) return;
    group.clearLayers();

    travelLines.forEach((line) => {
      if (line.points.length < 2) return;
      const latlngs = line.points as L.LatLngTuple[];
      const poly = L.polyline(latlngs, {
        color: line.color,
        weight: line.weight ?? 4,
        opacity: 0.95,
        dashArray: line.dashArray,
      });
      poly.bindPopup(
        `<strong>${line.label}</strong><br/>Planned journey leg`
      );
      poly.addTo(group);
    });

    travelMarkers.forEach((m) => {
      const icon = L.divIcon({
        className: 'travel-point-marker',
        html: `<div class="travel-point-dot" style="background:${m.color}"></div>`,
        iconSize: [14, 14],
        iconAnchor: [7, 7],
      });
      const mk = L.marker([m.lat, m.lon], { icon });
      mk.bindPopup(`<strong>${m.label}</strong>`);
      mk.addTo(group);
    });

    if (travelLines.length || travelMarkers.length) {
      const pts: L.LatLngExpression[] = [
        ...travelLines.flatMap((l) => l.points),
        ...travelMarkers.map((m) => [m.lat, m.lon] as L.LatLngTuple),
      ];
      map.fitBounds(L.latLngBounds(pts), { padding: [40, 40], maxZoom: 15 });
    }
  }, [travelLines, travelMarkers, useLeaflet]);

  // ---- route-gaps seam overlay -----------------------------------------
  // The selected corridor seam draws its leg corridors (amber = terminating
  // leg, slate dashed = through-service leg) plus a terminal marker, and
  // zooms to fit.
  useEffect(() => {
    const group = seamLayerRef.current;
    const map = mapRef.current;
    if (!group || !map) return;
    group.clearLayers();
    if (!corridorSeam) return;

    const bounds: L.LatLngTuple[] = [];
    corridorSeam.legs.forEach((leg) => {
      const pts = leg.stops_geo
        .filter((s) => Number.isFinite(s.lat) && Number.isFinite(s.lon))
        .map((s) => [s.lat, s.lon] as L.LatLngTuple);
      if (pts.length < 2) return;
      const terminating = leg.terminates_at_terminal;
      const poly = L.polyline(pts, {
        color: terminating ? '#f59e0b' : '#94a3b8',
        weight: 5,
        opacity: 0.95,
        dashArray: terminating ? undefined : '6 5',
      });
      const first = leg.stops_geo[0];
      poly.bindPopup(
        `<strong>${corridorSeam.corridor}</strong><br/>` +
          `${leg.side} leg · routes ${leg.routes.join(', ')}` +
          (first ? `<br/>from ${first.name} outward` : '')
      );
      poly.addTo(group);
      bounds.push(...pts);
    });

    if (corridorSeam.terminal_geo) {
      const { lat, lon, name } = corridorSeam.terminal_geo;
      const icon = L.divIcon({
        className: 'seam-terminal-marker',
        html: `<div class="seam-terminal-dot"></div>`,
        iconSize: [16, 16],
        iconAnchor: [8, 8],
      });
      const mk = L.marker([lat, lon], { icon });
      mk.bindPopup(`<strong>${name}</strong><br/>corridor seam`);
      mk.addTo(group);
      bounds.push([lat, lon]);
    }

    if (bounds.length) {
      // The container can be resized by React layout without a window resize
      // event (sidebar / panel switches), so Leaflet's internal size goes
      // stale and fitBounds computes the wrong zoom - re-measure first.
      map.invalidateSize();
      map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50], maxZoom: 16 });
    }
  }, [corridorSeam, useLeaflet]);

  // ---- optimizer re-phase overlay -------------------------------------
  // After the solver runs, the routes it moved draw in direction colors
  // (blue = runs earlier, amber = runs later) with a badge showing the signed
  // offset, so the "what changed" view renders on the map without needing the
  // travel planner. The base network is dimmed by the highlight effect above.
  useEffect(() => {
    const group = shiftLayerRef.current;
    if (!group) return;
    group.clearLayers();
    if (optimizeShifts.length === 0) return;
    const byRoute = new Map(
      (circuity?.features ?? []).map((f) => [f.properties.route_short_name, f])
    );
    optimizeShifts.forEach((s) => {
      const f = byRoute.get(s.route_short_name);
      if (!f) return;
      const coords = f.geometry.coordinates as [number, number][];
      if (coords.length < 2) return;
      const latlngs = coords.map(([lon, lat]) => [lat, lon] as L.LatLngTuple);
      const earlier = s.offset_minutes < 0;
      const color = earlier ? SHIFT_EARLIER_COLOR : SHIFT_LATER_COLOR;
      const weight = 2.5 + Math.min(4, Math.abs(s.offset_minutes));
      const poly = L.polyline(latlngs, { color, weight, opacity: 1 });
      poly.bindPopup(
        `<strong>Route ${s.route_short_name}</strong><br/>` +
          `moved ${earlier ? 'earlier' : 'later'} by ${Math.abs(s.offset_minutes)} min`
      );
      poly.addTo(group);
      // Offset badge at the route's midpoint: "R42 +4m" / "R5 -3m".
      const mid = coords[Math.floor(coords.length / 2)];
      const label = `R${s.route_short_name} ${earlier ? '-' : '+'}${Math.abs(s.offset_minutes)}m`;
      const icon = L.divIcon({
        className: 'proposed-route-badge',
        html: `<div class="optimize-shift-badge" style="background:${color}">${label}</div>`,
        iconSize: [0, 0],
      });
      L.marker([mid[1], mid[0]], { icon, interactive: false }).addTo(group);
    });
}, [circuity, optimizeShifts, useLeaflet]);

   // ---- ward equity overlay -------------------------------------
   // Colors wards based on equity score (delta_minutes from equity report)
   useEffect(() => {
     const layer = wardLayerRef.current;
     const map = mapRef.current;
     if (!layer || !map || !wardBoundaries) return;

     // Clear existing layers
     layer.clearLayers();

     // If we have ward boundaries and scores, add them to the layer
     if (wardBoundaries && Object.keys(wardScores).length > 0) {
       layer.addData(wardBoundaries);
     }

     // Show/hide based on toggle
     if (showWardScores) {
       if (!map.hasLayer(layer)) {
         layer.addTo(map);
       }
     } else {
       map.removeLayer(layer);
     }
   }, [wardBoundaries, wardScores, showWardScores, useLeaflet]);

   // ---- map click -> pick a point (travel planner) ----------------------
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !onMapPick) return;
    const handler = (e: L.LeafletMouseEvent) => onMapPick(e.latlng.lat, e.latlng.lng);
    map.on('click', handler);
    return () => {
      map.off('click', handler);
    };
  }, [onMapPick, useLeaflet]);

  if (!useLeaflet) {
    return (
      <FallbackSvg
        circuity={circuity}
        nodes={nodes}
        showRoutes={showRoutes}
        showSplits={showSplits}
        showNodes={showNodes}
        showOneWay={showOneWay}
        travelLines={travelLines}
        travelMarkers={travelMarkers}
        onMapPick={onMapPick}
        pickActive={pickActive}
      />
    );
  }

  return (
    <div className="relative h-full w-full">
      <div
        ref={containerRef}
        className={`h-full w-full ${pickActive ? 'cursor-crosshair' : ''}`}
        style={{ background: '#e7e9eb' }}
      />
{/* Circuity key — swatches call circuityColor so map and key can never drift.
     Only shown when circuity routes are actually drawn. */}
{showRoutes && circuity && (
<div className="pointer-events-none absolute bottom-7 left-2 z-[1000] rounded bg-white/90 px-2.5 py-1.5 text-[10px] leading-4 text-slate-700 shadow-sm">
  <div className="font-semibold text-slate-600">How winding is the route?</div>
  <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1">
    {LEGEND_STOPS.map((s) => (
      <span key={s.label} className="flex items-center gap-1">
        <span
          className="inline-block h-1.5 w-4 rounded-sm"
          style={{ background: circuityColor(s.c) }}
        />
        {s.label}
      </span>
    ))}
  </div>
</div>
)}
<div className="pointer-events-none absolute left-2 top-2 z-[1000] flex items-center gap-2 rounded bg-white/90 px-2 py-1 text-[10px] text-slate-700 shadow-sm">
  Leaflet · {basemap.label}{tileNote ? ` · ${tileNote}` : ''}
  <BasemapPicker className="-my-1" />
  <span className="ml-1 cursor-pointer hover:text-white" onClick={() => setShowWardScores(!showWardScores)}>
    · Ward scores: {showWardScores ? 'on' : 'off'}
  </span>
  {optimizeShifts.length > 0 && (
    <span className="ml-1">
      · <span style={{ color: SHIFT_EARLIER_COLOR }}>●</span> earlier{' '}
      <span style={{ color: SHIFT_LATER_COLOR }}>●</span> later
    </span>
  )}
</div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* SVG fallback renderer — dependency-free, works everywhere          */
/* ------------------------------------------------------------------ */

const DEFAULT_BOUNDS = { minLon: -79.9, maxLon: -79.35, minLat: 43.5, maxLat: 43.72 };

function project(lon: number, lat: number, bounds: typeof DEFAULT_BOUNDS, w: number, h: number) {
  const x = ((lon - bounds.minLon) / (bounds.maxLon - bounds.minLon)) * w;
  const y = ((bounds.maxLat - lat) / (bounds.maxLat - bounds.minLat)) * h;
  return [x, y] as const;
}

function FallbackSvg({
  circuity,
  nodes,
  showRoutes,
  showSplits,
  showNodes,
  showOneWay,
  highlightedRoute,
  travelLines = [],
  travelMarkers = [],
  onMapPick,
  pickActive = false,
  showProposedNetwork = false,
  optimizeShifts = [],
}: Props) {
  const W = 900;
  const H = 560;
  const [bounds, setBounds] = useState<typeof DEFAULT_BOUNDS | null>(null);

  useEffect(() => {
    if (!circuity) return;
    let minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity;
    circuity.features.forEach((f) => {
      f.geometry.coordinates.forEach(([lon, lat]) => {
        if (lon < minLon) minLon = lon;
        if (lon > maxLon) maxLon = lon;
        if (lat < minLat) minLat = lat;
        if (lat > maxLat) maxLat = lat;
      });
    });
    nodes.forEach((n) => {
      if (n.lon < minLon) minLon = n.lon;
      if (n.lon > maxLon) maxLon = n.lon;
      if (n.lat < minLat) minLat = n.lat;
      if (n.lat > maxLat) maxLat = n.lat;
    });
    const padLon = (maxLon - minLon) * 0.05 || 0.02;
    const padLat = (maxLat - minLat) * 0.05 || 0.02;
    if (!Number.isFinite(minLon) || !Number.isFinite(maxLon)) {
      // No geometry at all (empty FeatureCollection, no nodes): fall back to
      // the default city bounds instead of projecting onto NaN.
      setBounds(null);
      return;
    }
    setBounds({ minLon: minLon - padLon, maxLon: maxLon + padLon, minLat: minLat - padLat, maxLat: maxLat + padLat });
  }, [circuity, nodes]);

  const b = bounds ?? DEFAULT_BOUNDS;
  const point = (lon: number, lat: number) => project(lon, lat, b, W, H);

  const palette = useMemo(
    () =>
      routePalette(
        (circuity?.features ?? [])
          .filter((f) => f.properties.flagged && f.properties.proposed_split)
          .map((f) => f.properties.route_short_name)
      ),
    [circuity]
  );

  const onSvgClick = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!onMapPick) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * W;
    const y = ((e.clientY - rect.top) / rect.height) * H;
    const lon = b.minLon + (x / W) * (b.maxLon - b.minLon);
    const lat = b.maxLat - (y / H) * (b.maxLat - b.minLat);
    onMapPick(lat, lon);
  };

  const gridLines: JSX.Element[] = [];
  for (let i = 0; i <= 9; i++) {
    const x = (W / 9) * i;
    gridLines.push(<line key={`v${i}`} x1={x} y1={0} x2={x} y2={H} stroke="#d8dde3" strokeWidth={1} />);
    const y = (H / 7) * i;
    gridLines.push(<line key={`h${i}`} x1={0} y1={y} x2={W} y2={y} stroke="#d8dde3" strokeWidth={1} />);
  }

  return (
    <div className={`relative h-full w-full overflow-hidden bg-[#f3f4f6] ${pickActive ? 'cursor-crosshair' : ''}`}>
      <svg viewBox={`0 0 ${W} ${H}`} className="h-full w-full" preserveAspectRatio="xMidYMid meet" onClick={onSvgClick}>
        {gridLines}
        {showRoutes &&
          circuity?.features
            // In proposed-network mode today's routes are not drawn at all;
            // the trunk + feeder lines below are the network.
            .filter(() => !showProposedNetwork)
            .map((f, i) => {
              const d = f.geometry.coordinates
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              const baseOpacity = showProposedNetwork ? 0.15 : optimizeShifts.length > 0 ? 0.08 : 1;
              return (
                <g key={`r-${i}`}>
                  {/* dark casing so the vivid line reads on light/muted basemaps */}
                  <path
                    d={d}
                    fill="none"
                    stroke="#233244"
                    strokeWidth={5}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    opacity={baseOpacity * 0.55}
                  />
                  <path
                    d={d}
                    fill="none"
                    stroke={circuityColor(f.properties.circuity)}
                    strokeWidth={2.6}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    opacity={baseOpacity}
                  />
                </g>
              );
            })}
        {showSplits &&
          circuity?.features
            .filter((f) => f.properties.flagged && f.properties.proposed_split)
            .flatMap((f) => {
              const p = f.properties.proposed_split!;
              const color = palette.get(f.properties.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const route = f.properties.route_short_name;
              const parts: {
                part: 'trunk' | 'branch';
                coords: [number, number][];
                color: string;
                route: string;
              }[] = [
                { part: 'trunk', coords: p.trunk_geometry, color, route },
              ];
              p.branches.forEach((b) => parts.push({ part: 'branch', coords: b.geometry, color, route }));
              return parts;
            })
            .map(({ part, coords, color, route }, i) => {
              // Focus mode: unselected candidates draw muted grey; the selected
              // route pops in its hue. Show-all mode: every route in its hue,
              // selected pops via weight.
              const hl = highlightedRoute != null && route === highlightedRoute;
              const effColor = showProposedNetwork
                ? color
                : hl
                  ? color
                  : PROPOSED_MUTED_COLOR;
              const effOpacity = showProposedNetwork
                ? highlightedRoute != null
                  ? hl
                    ? 1
                    : 0.55
                  : 1
                : hl
                  ? 1
                  : 0.4;
              const effWeight = showProposedNetwork || hl
                ? part === 'trunk'
                  ? 5
                  : 3.5
                : part === 'trunk'
                  ? 3
                  : 2.5;
              const d = coords
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              return (
                <path
                  key={`s-${part}-${i}`}
                  d={d}
                  fill="none"
                  stroke={effColor}
                  strokeWidth={effWeight}
                  opacity={effOpacity}
                  strokeDasharray={part === 'branch' ? '6 5' : undefined}
                  strokeLinecap="round"
                />
              );
            })}
        {showSplits &&
          circuity?.features
            .filter((f) => f.properties.flagged && f.properties.proposed_split?.splice_junctions?.length)
            // Focus mode: only the selected route's dots draw, so the map
            // stays uncluttered; show-all mode draws every splice's dots.
            .filter(
              (f) =>
                showProposedNetwork ||
                (highlightedRoute != null &&
                  f.properties.route_short_name === highlightedRoute)
            )
            .flatMap((f) => {
              const color = palette.get(f.properties.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const p = f.properties.proposed_split!;
              return p.splice_junctions!.map((j, k) => ({
                key: `j-${f.properties.route_short_name}-${k}`,
                color,
                j,
                k,
                route: f.properties.route_short_name,
                donor: p.donor_route,
              }));
            })
            .map(({ key, color, j, k, route, donor }) => {
              const [x, y] = point(j.lon, j.lat);
              return (
                <g key={key}>
                  <circle cx={x} cy={y} r={7} fill="#ffffff" stroke={color} strokeWidth={2.5} />
                  <circle cx={x} cy={y} r={4.5} fill={color} />
                  <title>{`Route ${route} — ${k === 0 ? 'leaves' : 'rejoins'} Route ${donor}'s routing: ${j.label}`}</title>
                </g>
              );
            })}
        {(showProposedNetwork || highlightedRoute != null) &&
          circuity?.features
            .filter((f) => f.properties.flagged && f.properties.proposed_split)
            // Focus mode labels only the selected route; show-all labels all.
            .filter(
              (f) =>
                showProposedNetwork ||
                f.properties.route_short_name === highlightedRoute
            )
            .flatMap((f) => {
              const p = f.properties.proposed_split!;
              const color = palette.get(f.properties.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const labels: { label: string; color: string; coords: [number, number][]; solid: boolean }[] = [
                { label: f.properties.route_short_name, color, coords: p.trunk_geometry, solid: true },
              ];
              p.branches.forEach((b, i) =>
                labels.push({
                  label: `${f.properties.route_short_name}${String.fromCharCode(65 + i)}`,
                  color,
                  coords: b.geometry,
                  solid: false,
                })
              );
              return labels;
            })
            .map(({ label, color, coords, solid }, i) => {
              if (coords.length < 2) return null;
              const mid = coords[Math.floor(coords.length / 2)];
              const [x, y] = point(mid[0], mid[1]);
              return solid ? (
                <g key={`pl-${i}`}>
                  <rect
                    x={x - 11}
                    y={y - 8}
                    width={22}
                    height={16}
                    rx={8}
                    fill={color}
                  />
                  <text
                    x={x}
                    y={y + 3.5}
                    textAnchor="middle"
                    fontSize={9.5}
                    fontWeight={700}
                    fill="#ffffff"
                  >
                    {label}
                  </text>
                </g>
              ) : (
                <g key={`pl-${i}`}>
                  <rect
                    x={x - 12}
                    y={y - 8}
                    width={24}
                    height={16}
                    rx={6}
                    fill="rgba(255,255,255,0.95)"
                    stroke={color}
                    strokeWidth={1.5}
                  />
                  <text
                    x={x}
                    y={y + 3.5}
                    textAnchor="middle"
                    fontSize={9.5}
                    fontWeight={700}
                    fill={color}
                  >
                    {label}
                  </text>
                </g>
              );
            })}
        {showOneWay &&
          circuity?.features
            .filter((f) => f.properties.one_way)
            .map((f, i) => {
              const coords = f.geometry.coordinates;
              const d = coords
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              const step = Math.max(1, Math.floor(coords.length / 6));
              const arrows = [];
              for (let j = 0; j < coords.length - 1; j += step) {
                const a = coords[j];
                const b = coords[Math.min(j + 1, coords.length - 1)];
                const [ax, ay] = point(a[0], a[1]);
                const [bx, by] = point(b[0], b[1]);
                const mx = (ax + bx) / 2;
                const my = (ay + by) / 2;
                const ang = (Math.atan2(by - ay, bx - ax) * 180) / Math.PI;
                arrows.push(
                  <g key={j} transform={`translate(${mx.toFixed(1)},${my.toFixed(1)}) rotate(${ang.toFixed(1)})`}>
                    <path d="M-6,-4 L4,0 L-6,4" fill="none" stroke={ONE_WAY_COLOR} strokeWidth={2} />
                  </g>
                );
              }
              return (
                <g key={`ow-${i}`}>
                  <path
                    d={d}
                    fill="none"
                    stroke={ONE_WAY_COLOR}
                    strokeWidth={3}
                    strokeDasharray="8 6"
                    strokeLinecap="round"
                  />
                  {arrows}
                </g>
              );
            })}
        {showNodes &&
          nodes.map((n) => {
            const [x, y] = point(n.lon, n.lat);
            const r = 3 + n.friction_score * 0.3;
            const color = n.friction_score > 30 ? '#FF5252' : n.friction_score > 20 ? '#FFB300' : '#00E676';
            return (
              <g key={n.stop_id}>
                <circle cx={x} cy={y} r={r} fill={color} opacity={0.95} stroke="#1f2937" strokeWidth={1} />
                <title>{`${n.stop_name} — friction ${n.friction_score}`}</title>
              </g>
            );
          })}
        {travelLines.map((line) => {
          const d = line.points
            .map(([lat, lon], j) => {
              const [x, y] = point(lon, lat);
              return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
            })
            .join(' ');
          return (
            <path
              key={`tl-${line.id}`}
              d={d}
              fill="none"
              stroke={line.color}
              strokeWidth={line.weight ?? 5}
              strokeDasharray={line.dashArray}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          );
        })}
        {optimizeShifts.length > 0 &&
          optimizeShifts
            .map((s) => {
              const f = circuity?.features.find(
                (x) => x.properties.route_short_name === s.route_short_name
              );
              if (!f) return null;
              const earlier = s.offset_minutes < 0;
              const color = earlier ? SHIFT_EARLIER_COLOR : SHIFT_LATER_COLOR;
              const d = f.geometry.coordinates
                .map((c, j) => {
                  const [x, y] = point(c[0], c[1]);
                  return `${j === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
                })
                .join(' ');
              const mid = f.geometry.coordinates[Math.floor(f.geometry.coordinates.length / 2)];
              const [mx, my] = point(mid[0], mid[1]);
              return {
                key: s.route_short_name,
                d,
                color,
                weight: 2.5 + Math.min(4, Math.abs(s.offset_minutes)),
                label: `R${s.route_short_name} ${earlier ? '-' : '+'}${Math.abs(s.offset_minutes)}m`,
                mx,
                my,
              };
            })
            .filter(
              (o): o is {
                key: string;
                d: string;
                color: string;
                weight: number;
                label: string;
                mx: number;
                my: number;
              } => o !== null
            )
            .map((o) => (
              <g key={o.key}>
                <path
                  d={o.d}
                  fill="none"
                  stroke={o.color}
                  strokeWidth={o.weight}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
                <g transform={`translate(${o.mx.toFixed(1)},${o.my.toFixed(1)})`}>
                  <rect x={-14} y={-8} width={28} height={16} rx={8} fill={o.color} />
                  <text
                    x={0}
                    y={3.5}
                    textAnchor="middle"
                    fontSize={9.5}
                    fontWeight={700}
                    fill="#ffffff"
                  >
                    {o.label}
                  </text>
                </g>
              </g>
            ))}
        {travelMarkers.map((m) => {
          const [x, y] = point(m.lon, m.lat);
          return (
            <g key={`tm-${m.id}`}>
              <circle cx={x} cy={y} r={7} fill={m.color} stroke="#ffffff" strokeWidth={2} />
              <title>{m.label}</title>
            </g>
          );
        })}
      </svg>
      <div className="absolute left-2 top-2 rounded bg-white/90 px-2 py-1 text-[10px] text-slate-700 shadow-sm">
        SVG preview
      </div>
      {!circuity && (
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="rounded bg-white/90 px-3 py-1.5 text-sm text-slate-600 shadow-sm">
            Loading route geometry…
          </span>
        </div>
      )}
    </div>
  );
}
