import { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, ArrowRight, Bus, CornerUpLeft, Eye, EyeOff, GitBranch, Info, Layers, MapPin, TrendingDown, Unlink } from 'lucide-react';
import { api } from '../lib/api';
import type { CircuityGeoJSON, CircuitySummaryRoute, CorridorGap, CorridorGapsResponse } from '../types';
import { PROPOSED_MUTED_COLOR, routePalette } from './MapView';

// Fallback hue if a proposal is somehow missing from the shared palette.
const PROPOSED_DEFAULT_COLOR = '#FFB300';

/**
 * Trunk & feeder panel: the proposed trunk + feeder decomposition for every
 * flagged winding route, in plain language. A route may propose several
 * feeders when its winding part is itself worth re-splitting.
 *
 * "Trunk" = the direct main line. "Feeder" = a shorter branch that serves
 * the local stops the old winding route used to cover.
 */

interface Props {
  circuity: CircuityGeoJSON | null;
  /** Full flagged list; used to pair each proposal with the route's overall score. */
  flaggedRoutes: CircuitySummaryRoute[];
  highlightedRoute: string | null;
  onHighlight: (routeShortName: string | null) => void;
  /** Whether the map draws every proposal at once with route-number badges. */
  showProposedNetwork: boolean;
  onToggleProposedNetwork: (on: boolean) => void;
  /** Fired when a corridor gap is selected/deselected, so the map can draw the seam. */
  onCorridorFocus?: (seam: CorridorGap | null) => void;
}

interface SplitBranch {
  circuity: number;
  length_km: number;
  start_terminal: string;
  end_terminal: string;
  /** [lon, lat] vertices — used to find where the feeder meets the trunk. */
  geometry: [number, number][];
  /** Allocated headway (min) for this feeder, or null when unavailable. */
  headway_min?: number | null;
}

interface SplitProposal {
  route_short_name: string;
  route_long_name: string;
  full_circuity: number;
  full_length_km: number;
  trunk_circuity: number;
  trunk_length_km: number;
  trunk_start_terminal: string;
  trunk_end_terminal: string;
  /** When set, the trunk borrows this route's direct alignment (corridor splice). */
  donor_route?: string | null;
  /** The two corridor junctions (leave / rejoin) for spliced trunks. */
  splice_junctions?: { lat: number; lon: number; label: string }[] | null;
  /** Where the trunk came from: donor / network / meander (see types/index.ts). */
  trunk_source: string;
  branches: SplitBranch[];
  /** True when the trunk borrowed another route's corridor (has donor note + junction dots). */
  isDonorSplice: boolean;
  /** [lon, lat] vertices of the proposed trunk line (branch-off math). */
  trunkGeometry: [number, number][];
  /** Route's existing headway (min) — the baseline each piece is compared against. */
  route_headway_min?: number | null;
  /** Allocated headway (min) for the trunk, or null when unavailable. */
  trunk_headway_min?: number | null;
  /** How the headway allocation was derived (ridership_weighted / route_headway / ...). */
  headway_method?: string | null;
}

/** Feeder label suffix: A, B, C, ... */
function branchLetter(i: number): string {
  return String.fromCharCode(65 + i);
}

/** Squared lon/lat distance from a point to a segment. */
function segDist2(
  lon: number,
  lat: number,
  a: [number, number],
  b: [number, number]
): number {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const len2 = dx * dx + dy * dy;
  let t = len2 === 0 ? 0 : ((lon - a[0]) * dx + (lat - a[1]) * dy) / len2;
  t = Math.max(0, Math.min(1, t));
  const px = a[0] + t * dx - lon;
  const py = a[1] + t * dy - lat;
  return px * px + py * py;
}

/** Squared lon/lat distance from a point to a polyline ([lon, lat] vertices). */
function pointToLineDist2(
  lon: number,
  lat: number,
  line: [number, number][]
): number {
  let best = Infinity;
  for (let i = 0; i < line.length - 1; i++) {
    const d = segDist2(lon, lat, line[i], line[i + 1]);
    if (d < best) best = d;
  }
  return best;
}

/**
 * The stop where a feeder meets the trunk. A feeder is an off-trunk segment
 * of the old route: one endpoint touches the proposed trunk (the branch-off
 * point), the other is the far end that keeps the dropped stops. We compare
 * the branch's two endpoints against the trunk line and name the closer one.
 * (Donor splices don't need this — their junction dots are exact.)
 */
function feederBranchOff(branch: SplitBranch, trunk: [number, number][]): string {
  const coords = branch.geometry;
  if (!coords || coords.length < 2 || trunk.length < 2) return branch.end_terminal;
  const d0 = pointToLineDist2(coords[0][0], coords[0][1], trunk);
  const d1 = pointToLineDist2(coords[coords.length - 1][0], coords[coords.length - 1][1], trunk);
  return d0 <= d1 ? branch.start_terminal : branch.end_terminal;
}

/** One-line "what is this route doing" summary shown on each list row. */
function routeStory(p: SplitProposal): string {
  if (p.isDonorSplice && p.donor_route && p.splice_junctions?.length === 2) {
    const [a, b] = p.splice_junctions;
    return `Leaves its corridor at ${a.label} and rejoins at ${b.label} — the trunk borrows Route ${p.donor_route}'s direct routing between them.`;
  }
  if (p.trunk_source === 'network') {
    return `Winds through the old routing today — the new trunk goes direct from ${p.trunk_start_terminal} to ${p.trunk_end_terminal}, and the feeder(s) keep the old stops.`;
  }
  return 'No corridor to borrow — the route is split at its worst meander.';
}

export default function TrunkFeederPanel({
  circuity,
  flaggedRoutes,
  highlightedRoute,
  onHighlight,
  showProposedNetwork,
  onToggleProposedNetwork,
  onCorridorFocus,
}: Props) {
  const proposals = useMemo<SplitProposal[]>(() => {
    if (!circuity) return [];
    const out: SplitProposal[] = [];
    circuity.features.forEach((f) => {
      const p = f.properties;
      // Every route with a split proposal belongs here. Donor splices borrow
      // another route's direct corridor (a real redesign with junction dots);
      // network trunks are NEW direct lines routed over the street network
      // (no donor, no junction dots -- the old route's winding stretches
      // become feeders); meander splits are the route's own shape cut at its
      // worst meander. The row says which one instead of implying it.
      if (!p.flagged || !p.proposed_split) return;
      const full = flaggedRoutes.find((r) => r.route_short_name === p.route_short_name);
      const trunkSource =
        p.proposed_split.trunk_source ??
        (p.proposed_split.donor_route ? 'donor' : 'meander');
      out.push({
        route_short_name: p.route_short_name,
        route_long_name: p.route_long_name,
        full_circuity: full?.circuity ?? p.circuity,
        full_length_km: full?.length_km ?? p.length_km,
        trunk_circuity: p.proposed_split.trunk_circuity,
        trunk_length_km: p.proposed_split.trunk_length_km,
        trunk_start_terminal: p.proposed_split.trunk_start_terminal,
        trunk_end_terminal: p.proposed_split.trunk_end_terminal,
        donor_route: p.proposed_split.donor_route ?? null,
        splice_junctions: p.proposed_split.splice_junctions ?? null,
        trunk_source: trunkSource,
        isDonorSplice: trunkSource === 'donor',
        trunkGeometry: p.proposed_split.trunk_geometry as [number, number][],
        route_headway_min: p.proposed_split.route_headway_min ?? null,
        trunk_headway_min: p.proposed_split.trunk_headway_min ?? null,
        headway_method: p.proposed_split.headway_method ?? null,
        branches: p.proposed_split.branches.map((b) => ({
          circuity: b.circuity,
          length_km: b.length_km,
          start_terminal: b.start_terminal,
          end_terminal: b.end_terminal,
          headway_min: b.headway_min ?? null,
          geometry: b.geometry as [number, number][],
        })),
      });
    });
    // Most winding first, matching the flagged ranking in Route quality.
    return out.sort((a, b) => b.full_circuity - a.full_circuity);
  }, [circuity, flaggedRoutes]);

  const selected = useMemo(
    () => proposals.find((p) => p.route_short_name === highlightedRoute) ?? null,
    [proposals, highlightedRoute]
  );

  // Same per-route hues the map uses, so each row's badges match the overlay.
  const proposalColors = useMemo(
    () => routePalette(proposals.map((p) => p.route_short_name)),
    [proposals]
  );
  const colorFor = (name: string) => proposalColors.get(name) ?? PROPOSED_DEFAULT_COLOR;

  // ---- corridor gaps (terminal seams) -------------------------------------
  const [gaps, setGaps] = useState<CorridorGapsResponse | null>(null);
  const [gapsLoading, setGapsLoading] = useState(true);
  const [selectedGap, setSelectedGap] = useState<CorridorGap | null>(null);

  useEffect(() => {
    let active = true;
    api.corridorGaps().then((d) => {
      if (active) { setGaps(d); setGapsLoading(false); }
    }).catch(() => { if (active) setGapsLoading(false); });
    return () => { active = false; };
  }, []);

  if (proposals.length === 0 && !gaps?.seams?.length) {
    return (
      <div className="rounded-xl border border-optimized/40 bg-card p-4 text-sm text-text-muted">
        <div className="flex items-center gap-2 text-xs font-semibold text-optimized">
          <Info className="h-4 w-4" />
          No splits to propose
        </div>
        <p className="mt-2 text-[11px] leading-relaxed">
          No route leaves and rejoins a corridor worth borrowing in this period. Try another time
          period — rush-hour-only routes appear in AM/PM rush.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      {/* ---- concept + legend ------------------------------------------ */}
      <section className="rounded-xl border border-border bg-card p-4">
        <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <GitBranch className="h-4 w-4 text-accent" />
          Trunk &amp; feeder
        </div>
        <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
          Instead of one bus snaking across the whole corridor, each route is shortened at a real
          junction: where it leaves its main corridor and rejoins it later, the{' '}
          <span className="font-semibold text-optimized">trunk</span> borrows the direct routing
          of the existing route that already runs that corridor (the white-ring dots), and a{' '}
          <span className="font-semibold text-accent">feeder</span> takes over the dropped span
          so no stop loses service. Routes with no corridor to borrow get a brand-new direct trunk
          routed over the existing street network instead of a cut of their own winding shape. No
          street geometry is invented — every line follows streets some MiWay bus drives today.
        </p>

        <div className="mt-3 rounded-lg border border-border bg-bg p-2.5">
          <div className="flex items-center gap-2 text-[10px] font-semibold uppercase tracking-wide text-text-muted">
            <Layers className="h-3 w-3" />
            How to read the map
          </div>
          <div className="mt-2 space-y-1.5">
            <div className="flex items-center gap-2">
              <span className="h-0.5 w-8 rounded bg-text-secondary" />
              <span className="text-[11px] text-text-secondary">
                <span className="font-semibold text-text-primary">Trunk</span> — direct main route
              </span>
            </div>
            <div className="flex items-center gap-2">
              <svg width={32} height={8}>
                <line x1={0} y1={4} x2={32} y2={4} stroke="#9E9E9E" strokeWidth={2} strokeDasharray="5 3" />
              </svg>
              <span className="text-[11px] text-text-secondary">
                <span className="font-semibold text-text-primary">Feeder</span> — local branch keeping old stops
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span
                className="inline-block h-3 w-3 shrink-0 rounded-full border-2 border-white"
                style={{ background: PROPOSED_DEFAULT_COLOR, boxShadow: '0 0 0 1px rgba(0,0,0,0.25)' }}
              />
              <span className="text-[11px] text-text-secondary">
                <span className="font-semibold text-text-primary">Junction dot</span> — trunk leaves / rejoins corridor
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="h-0.5 w-8 rounded" style={{ background: PROPOSED_MUTED_COLOR }} />
              <span className="text-[11px] text-text-secondary">
                <span className="font-semibold text-text-primary">Muted</span> — unselected route (pick one to focus)
              </span>
            </div>
          </div>
        </div>

        <button
          onClick={() => onToggleProposedNetwork(!showProposedNetwork)}
          className={`mt-3 flex w-full items-center justify-between rounded-lg border px-3 py-2 text-left transition-colors ${
            showProposedNetwork
              ? 'border-optimized/50 bg-optimized/10 hover:bg-optimized/20'
              : 'border-border bg-card-hover hover:bg-border'
          }`}
        >
          <span>
            <span className="block text-[11px] font-bold text-text-primary">
              {showProposedNetwork
                ? 'Showing complete proposed network'
                : 'Focus view — one route at a time'}
            </span>
            <span className="mt-0.5 block text-[10px] leading-snug text-text-muted">
              {showProposedNetwork
                ? 'All proposals shown with route badges. Pick a route to highlight it.'
                : 'Pick a route to see its trunk + feeders in colour.'}
            </span>
          </span>
          {showProposedNetwork ? (
            <Eye className="ml-2 h-4 w-4 shrink-0 text-optimized" />
          ) : (
            <EyeOff className="ml-2 h-4 w-4 shrink-0 text-text-muted" />
          )}
        </button>
      </section>

      {/* ---- route list --------------------------------------------- */}
      <section className="rounded-xl border border-border bg-card p-4">
        <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <MapPin className="h-4 w-4 text-bottleneck" />
          Proposed trunk + feeder splits
        </div>
        <p className="mt-1 text-[11px] leading-relaxed text-text-muted">
          Sorted by how winding the full route is today. Routes that leave and rejoin a real
          corridor borrow the donor&apos;s direct alignment (marked <span className="font-semibold text-optimized">borrows</span>,
          with white-ring junction dots on the map). Routes with no corridor to borrow get a{' '}
          <span className="font-semibold text-optimized">new direct trunk</span> routed over the
          existing street network — the old route&apos;s winding stretches become the feeders, so no
          stops are dropped. Only when that isn&apos;t worth it is the route cut at its worst meander
          instead (marked <span className="font-semibold text-text-secondary">no corridor</span>,
          e.g. 36) — still a real split, but built from the route&apos;s own shape.
        </p>
        <ul className="mt-3 space-y-1.5">
          {proposals.map((p) => (
            <li
              key={p.route_short_name}
              onClick={() =>
                onHighlight(highlightedRoute === p.route_short_name ? null : p.route_short_name)
              }
              className={`flex cursor-pointer flex-col gap-1 rounded-lg px-2.5 py-2 text-xs transition-colors ${
                highlightedRoute === p.route_short_name
                  ? 'bg-accent/15 ring-1 ring-accent'
                  : 'bg-card-hover hover:bg-border'
              }`}
            >
              <span className="flex items-center justify-between">
                <span className="font-medium text-text-primary">
                  Route {p.route_short_name}
                  {p.route_long_name ? (
                    <span className="ml-1.5 text-[10px] text-text-muted">{p.route_long_name}</span>
                  ) : null}
                </span>
                <span className="font-semibold text-bottleneck">
                  {p.full_circuity.toFixed(2)}× today
                </span>
              </span>
              <span className="mt-0.5 block text-[10px] font-semibold text-optimized/90">
                One route → trunk + feeders: same fleet, no new buses
              </span>
              <p className="mt-1 text-[10px] leading-snug text-text-muted">
                {routeStory(p)}
              </p>
              <span className="mt-1.5 space-y-1.5 border-t border-border/60 pt-1.5">
                <PieceRow
                  badge={p.route_short_name}
                  label="Trunk"
                  solid
                  color={colorFor(p.route_short_name)}
                  circuity={p.trunk_circuity}
                  lengthKm={p.trunk_length_km}
                  start={p.trunk_start_terminal}
                  end={p.trunk_end_terminal}
                  donorRoute={p.donor_route}
                  isDonorSplice={p.isDonorSplice}
                  trunkSource={p.trunk_source}
                  headwayMin={p.trunk_headway_min}
                  routeHeadwayMin={p.route_headway_min}
                />
                {p.branches.map((b, i) => {
                  const j = p.splice_junctions;
                  const feederNote =
                    p.isDonorSplice && j && j.length >= 2
                      ? `Branches off the trunk at ${j[0].label}, covers the old routing to ${j[1].label}`
                      : p.trunk_source === 'network'
                        ? `Branches off the new trunk near ${feederBranchOff(
                            b,
                            p.trunkGeometry
                          )} — keeps the old stops served`
                        : 'Serves the route\u2019s own shape from the meander split point';
                  return (
                    <PieceRow
                      key={`${b.end_terminal}-${i}`}
                      badge={`${p.route_short_name}${branchLetter(i)}`}
                      label={`Feeder ${branchLetter(i)}`}
                      solid={false}
                      color={colorFor(p.route_short_name)}
                      circuity={b.circuity}
                      lengthKm={b.length_km}
                      start={b.start_terminal}
                      end={b.end_terminal}
                      trunkSource={p.trunk_source}
                       isFeeder
                       feederNote={feederNote}
                       headwayMin={b.headway_min}
                       routeHeadwayMin={p.route_headway_min}
                     />
                  );
                })}
                {highlightedRoute === p.route_short_name && (
                  <span className="inline-flex items-center gap-1 pt-0.5 text-[10px] font-semibold text-accent">
                    On the map <ArrowRight className="h-3 w-3" />
                  </span>
                )}
              </span>
            </li>
          ))}
        </ul>
      </section>

      {/* ---- selected split detail ----------------------------------- */}
      {selected ? (
        <section className="rounded-xl border border-border bg-card p-4">
          <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
            <TrendingDown className="h-4 w-4 text-optimized" />
            What Route {selected.route_short_name} becomes
          </div>
          <div className="mt-3 flex items-baseline gap-2 rounded-lg bg-card-hover px-3 py-2 text-xs">
            <span className="text-text-muted">Full route</span>
            <span className="font-bold text-bottleneck">{selected.full_circuity.toFixed(2)}×</span>
            <ArrowRight className="h-3 w-3 text-text-muted" />
            <span className="text-text-muted">trunk</span>
            <span className="font-bold text-optimized">{selected.trunk_circuity.toFixed(2)}×</span>
          </div>
          <div className="mt-3 space-y-3">
            <SplitCard
              title="Main line (trunk)"
              badge={selected.route_short_name}
              color={colorFor(selected.route_short_name)}
              solid
              accent="text-optimized"
              bar="bg-optimized"
              circuity={selected.trunk_circuity}
              lengthKm={selected.trunk_length_km}
              terminals={[selected.trunk_start_terminal, selected.trunk_end_terminal]}
              donorRoute={selected.donor_route}
              isDonorSplice={selected.isDonorSplice}
              trunkSource={selected.trunk_source}
              junctions={selected.splice_junctions ?? undefined}
            />
            {selected.branches.map((b, i) => (
              <SplitCard
                key={`${b.end_terminal}-${i}`}
                title={`Feeder ${branchLetter(i)}`}
                badge={`${selected.route_short_name}${branchLetter(i)}`}
                color={colorFor(selected.route_short_name)}
                solid={false}
                accent="text-accent"
                bar="bg-accent"
                circuity={b.circuity}
                lengthKm={b.length_km}
                terminals={[b.start_terminal, b.end_terminal]}
              />
            ))}
            <p className="text-[10px] leading-snug text-text-muted">
              {selected.branches.length === 1 ? (
                <>
                  The feeder turns back at{' '}
                  <span className="text-text-primary">
                    {selected.branches[0].end_terminal}
                  </span>{' '}
                  instead of running the whole corridor, so riders on that segment no longer pay for
                  the trunk&apos;s detour — and the trunk itself gets more direct.
                </>
              ) : (
                <>
                  The {selected.branches.length} feeders turn back at their own terminals (
                  {selected.branches.map((b, i) => (
                    <span key={i} className="text-text-primary">
                      {b.end_terminal}
                      {i < selected.branches.length - 1 ? ' / ' : ''}
                    </span>
                  ))}
                  ) instead of running the whole corridor, so each segment only pays for its own
                  meander.
                </>
              )}
            </p>
          </div>
        </section>
      ) : (
        <p className="px-1 text-[10px] leading-snug text-text-muted">
          Select a route above to see its split in detail and on the map.
        </p>
      )}

      {/* ---- corridor gaps (terminal seams) ----------------------------- */}
      {gaps && gaps.seams.length > 0 && (
        <section className="mt-3 rounded-xl border border-border bg-card p-4">
          <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
            <Unlink className="h-4 w-4 text-bottleneck" />
            Route gaps — corridors severed at a terminal
          </div>
          <p className="mt-1 text-[11px] leading-relaxed text-text-muted">
            {gaps.note}
          </p>
          <div className="mt-3 flex flex-col divide-y divide-border overflow-hidden rounded-xl border border-border bg-bg/40">
            {gaps.seams.map((s) => (
              <button
                key={`${s.terminal}|${s.corridor}`}
                onClick={() => {
                  const next = selectedGap === s ? null : s;
                  setSelectedGap(next);
                  onCorridorFocus?.(next);
                }}
                className={`px-3 py-3 text-left transition-colors last:border-b-0 ${
                  selectedGap === s ? 'bg-accent/10' : 'hover:bg-card-hover/50'
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="text-xs font-bold text-text-primary">
                      {s.corridor}<span className="font-normal text-text-muted"> · {s.terminal}</span>
                    </div>
                    <div className="mt-1 text-[11px] leading-snug text-text-secondary">{s.story}</div>
                  </div>
                  <div className="shrink-0 text-right">
                    <div className="text-[11px] font-bold text-bottleneck">{s.n_terminating_routes} routes</div>
                    {s.boardings > 0 && (
                      <div className="text-[10px] text-text-muted">~{s.boardings.toLocaleString()} riders/day</div>
                    )}
                  </div>
                </div>
                <div className="mt-2 flex flex-wrap gap-1.5">
                  {s.legs.map((leg) => (
                    <span
                      key={leg.side}
                      className={`inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-[10px] ${
                        leg.terminates_at_terminal
                          ? 'border border-bottleneck/30 bg-bottleneck/10 text-bottleneck'
                          : 'border border-border bg-card-hover text-text-secondary'
                      }`}
                    >
                      {leg.terminates_at_terminal ? <Bus className="h-3 w-3" /> : <CornerUpLeft className="h-3 w-3" />}
                      {leg.side} · {leg.routes.length === 1 ? `Route ${leg.routes[0]}` : `Routes ${leg.routes.join(', ')}`}
                    </span>
                  ))}
                </div>
              </button>
            ))}
          </div>
          <div className="mt-2 flex items-start gap-1.5 rounded-lg border border-border bg-card-hover/40 px-3 py-2 text-[10px] leading-snug text-text-muted">
            <AlertTriangle className="mt-0.5 h-3 w-3 shrink-0 text-bottleneck" />
            <span>A seam is a transfer opportunity gap — some hubs are designed transfer points. The value is seeing where the transfer is forced.</span>
          </div>
        </section>
      )}
      {gapsLoading && (
        <section className="mt-3 rounded-xl border border-border bg-card p-4">
          <div className="text-[11px] text-text-muted">Scanning terminals for corridor gaps…</div>
        </section>
      )}
    </div>
  );
}

function terminalLabel(start: string, end: string): string {
  if (!start && !end) return 'terminal not set';
  if (!start) return end;
  if (!end) return start;
  return start === end ? `${start} (loop)` : `${start} → ${end}`;
}

/** Route-number pill matching the map: solid fill = trunk, outlined = feeder. */
function PieceBadge({
  label,
  color,
  solid,
}: {
  label: string;
  color: string;
  solid: boolean;
}) {
  return solid ? (
    <span
      className="inline-flex shrink-0 items-center justify-center rounded-full border-2 border-black/25 px-1.5 py-0.5 text-[9px] font-bold leading-none text-white"
      style={{ background: color, boxShadow: '0 1px 2px rgba(0, 0, 0, 0.3)' }}
    >
      {label}
    </span>
  ) : (
    <span
      className="inline-flex shrink-0 items-center justify-center rounded-full border-2 bg-bg px-1.5 py-0.5 text-[9px] font-bold leading-none"
      style={{ borderColor: color, color }}
    >
      {label}
    </span>
  );
}

/** One line of a proposal row: badge, role, metrics, and the piece's endpoints. */
function PieceRow({
  badge,
  label,
  solid,
  color,
  circuity,
  lengthKm,
  start,
  end,
  donorRoute,
  isDonorSplice,
  trunkSource,
  isFeeder,
  feederNote,
  headwayMin,
  routeHeadwayMin,
}: {
  badge: string;
  label: string;
  solid: boolean;
  color: string;
  circuity: number;
  lengthKm: number;
  start: string;
  end: string;
  donorRoute?: string | null;
  isDonorSplice?: boolean;
  trunkSource?: string;
  isFeeder?: boolean;
  /** Plain-language note for feeder rows (where it branches off the trunk). */
  feederNote?: string;
  /** Allocated headway (min) for this piece, or null when unavailable. */
  headwayMin?: number | null;
  /** Route's existing headway (min) — the baseline for comparison. */
  routeHeadwayMin?: number | null;
}) {
  return (
    <div className="flex items-start gap-2">
      <PieceBadge label={badge} color={color} solid={solid} />
      <div className="min-w-0 flex-1">
        <div className="flex items-baseline justify-between gap-2">
          <span className="text-[10px] font-semibold text-text-secondary">{label}</span>
          <span className="shrink-0 text-[10px] text-text-secondary">
            {circuity.toFixed(2)}× · {lengthKm.toFixed(1)} km
            {headwayMin != null ? ` · every ~${headwayMin} min` : ''}
          </span>
        </div>
        <p className="mt-0.5 text-[10px] leading-snug text-text-muted">
          {terminalLabel(start, end)}
        </p>
        {isFeeder && feederNote ? (
          <p className="mt-0.5 text-[10px] leading-snug text-accent">{feederNote}</p>
        ) : donorRoute ? (
          <p className="mt-0.5 text-[10px] leading-snug text-optimized">
            Takes the direct {donorRoute} routing for its straight stretch
          </p>
        ) : trunkSource === 'network' ? (
          <p className="mt-0.5 text-[10px] leading-snug text-optimized">
            New direct line routed over the existing street network
          </p>
        ) : isDonorSplice === false ? (
          <p className="mt-0.5 text-[10px] leading-snug text-text-secondary">
            No corridor to borrow — split from the route&apos;s own shape
          </p>
        ) : null}
        {isFeeder && headwayMin != null && routeHeadwayMin != null && headwayMin > routeHeadwayMin + 0.5 ? (
          <p className="mt-0.5 text-[10px] leading-snug text-text-muted">
            Local coverage — runs less often than the trunk
          </p>
        ) : null}
      </div>
    </div>
  );
}

function SplitCard({
  title,
  badge,
  color,
  solid,
  accent,
  bar,
  circuity,
  lengthKm,
  terminals,
  donorRoute,
  isDonorSplice,
  trunkSource,
  junctions,
}: {
  title: string;
  badge?: string;
  color?: string;
  solid?: boolean;
  accent: string;
  bar: string;
  circuity: number;
  lengthKm: number;
  terminals: [string, string];
  donorRoute?: string | null;
  isDonorSplice?: boolean;
  trunkSource?: string;
  junctions?: { lat: number; lon: number; label: string }[];
}) {
  return (
    <div>
      <div className="mb-1 flex items-center justify-between gap-2 text-[11px]">
        <span className="flex min-w-0 items-center gap-1.5">
          {badge && color ? (
            <PieceBadge label={badge} color={color} solid={solid ?? false} />
          ) : null}
          <span className={`truncate font-semibold ${accent}`}>{title}</span>
        </span>
        <span className="shrink-0 text-text-secondary">
          {lengthKm.toFixed(1)} km · <span className="font-semibold">{circuity.toFixed(2)}×</span>
        </span>
      </div>
      <div className="mb-1 h-1.5 w-full overflow-hidden rounded-full bg-card-hover">
        <div
          className={`h-full rounded-full ${bar}`}
          style={{ width: `${Math.min(100, (circuity / 2.5) * 100)}%` }}
        />
      </div>
      <p className="text-[10px] text-text-muted">
        {terminalLabel(terminals[0], terminals[1])}
      </p>
      {donorRoute ? (
        <p className="mt-1 text-[10px] leading-snug text-optimized">
          Borrows Route {donorRoute}&apos;s direct alignment between{' '}
          <span className="text-text-primary">{junctions?.[0]?.label ?? 'the first junction'}</span> and{' '}
          <span className="text-text-primary">{junctions?.[1]?.label ?? 'the second junction'}</span>
        </p>
      ) : trunkSource === 'network' ? (
        <p className="mt-1 text-[10px] leading-snug text-optimized">
          Routed as a new direct trunk over the street network — the old route&apos;s winding
          stretches become feeders, so no stops are dropped.
        </p>
      ) : isDonorSplice === false ? (
        <p className="mt-1 text-[10px] leading-snug text-text-secondary">
          No corridor to borrow — the split is cut from the route&apos;s own winding shape.
        </p>
      ) : null}
    </div>
  );
}
